.ig-svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.ig-svg line { stroke: rgba(143,163,191,.35); stroke-width: 2; animation: ig-linha 16s linear infinite; animation-delay: calc(var(--i, 0) * 2s - 16s); }
.ig-svg line.anel { stroke: rgba(192,138,30,.28); stroke-dasharray: 4 8; animation: none; }
.ig-hub { position: absolute; transform: translate(-50%, -50%); width: 150px; height: 150px; border-radius: 50%; display: grid; place-items: center; text-align: center; background: radial-gradient(closest-side, #16233A, #0B1220); border: 2px solid #C08A1E; box-shadow: 0 0 40px rgba(192,138,30,.35); font-size: 21px; font-weight: 700; line-height: 1.2; color: #F2D69C; }
