.ch-a { margin: 0; font: 500 clamp(1.15rem, 1.9vw, 1.4rem)/1.45 var(--body); color: #fff; }
.ch-a strong { color: #F2D69C; font-weight: 600; }
.ch-proof { margin: 1.2rem 0 0; padding-top: 1.1rem; border-top: 1px solid rgba(255,255,255,.16); color: #B9C3D1; font-size: 1rem; line-height: 1.5; }
.ch-ans a { color: #F2D69C; }
.ch-btns { display: flex; flex-wrap: wrap; align-items: center; gap: .6rem 1.2rem; margin-top: 1.5rem; }
.ch-ans .ch-btn { display: inline-flex; align-items: center; justify-content: center; min-height: 52px; padding: 0 1.4rem; border-radius: 4px; background: #C08A1E; color: #000; font: 700 1.05rem/1 var(--body); text-decoration: none; }
.ch-ans .ch-btn:hover { background: #D69C2A; }
.ch-ans .ch-more { display: inline-flex; align-items: center; min-height: 44px; color: #fff; font-weight: 600; }
.ch-ans :focus-visible { outline-color: #C08A1E; }
.ch-list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }
.ch-list li { display: grid; grid-template-columns: 44px 1fr; gap: 1rem; padding: 1.2rem 0; border-bottom: 1px solid var(--line); }
.ch-list svg { width: 44px; height: 44px; }
.ch-q { margin: 0; font: 600 1.12rem/1.3 var(--body); color: var(--ink); }
.ch-how { margin: .35rem 0 0; color: var(--slate); font-size: 1.02rem; line-height: 1.5; }
.ch-how b { display: inline-block; margin-right: .5rem; padding: .15rem .55rem; border-radius: 99px; background: #FBF3E2; color: #8A5C00; font-size: .8rem; font-weight: 700; letter-spacing: .02em; vertical-align: .08em; }
.ch-how a { color: var(--gold-text); }
@media (prefers-reduced-motion: no-preference) {
  .rv-on .ch-list li, .js .ch-list li { animation: ch-in .7s cubic-bezier(.2,.7,.2,1) both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
}
@keyframes ch-in { from { opacity: 0; translate: 24px 0; } to { opacity: 1; translate: 0 0; } }
