/* ===================== portfólio real (26/10/2026) ===================== */
/* sites criados pela Roque rolando dentro dos aparelhos; troca de site a cada ciclo */
.dv-real { --rc: 22s; }
.ui-real { display: flex; flex-direction: column; background: #000; }
.ui-real .bar span { position: relative; height: 2.6cqw; max-width: 46%; }
.ui-real .bar em { position: absolute; left: 2cqw; top: 50%; transform: translateY(-50%); font-style: normal; white-space: nowrap; }
.ui-real .vp { position: relative; flex: 1; overflow: hidden; }
.ui-real.m .vp { margin-top: 0; }
.ui-real .vp img { position: absolute; left: 0; top: 0; width: 100%; height: auto; display: block; will-change: transform, opacity; }
.dv-real .s1, .dv-real .u1 { animation: rs-s1 var(--rc) cubic-bezier(.45,.05,.35,1) infinite; }
.dv-real .s2, .dv-real .u2 { animation: rs-s2 var(--rc) cubic-bezier(.45,.05,.35,1) infinite; }
.dv-real .ui-real:not(.m) .vp img { --end: -74%; }
.dv-real .ui-real.m .vp img { --end: -61%; }
.dv-real .u1, .dv-real .u2 { --end: 0; }
@keyframes rs-s1 { 0% { opacity: 1; transform: translateY(0); } 7% { transform: translateY(0); } 40% { opacity: 1; transform: translateY(var(--end)); } 46% { opacity: 1; transform: translateY(var(--end)); } 50%, 95% { opacity: 0; transform: translateY(var(--end)); } 96% { opacity: 0; transform: translateY(0); } 100% { opacity: 1; transform: translateY(0); } }
@keyframes rs-s2 { 0%, 45% { opacity: 0; transform: translateY(0); } 50% { opacity: 1; transform: translateY(0); } 57% { transform: translateY(0); } 90% { opacity: 1; transform: translateY(var(--end)); } 96% { opacity: 1; transform: translateY(var(--end)); } 100% { opacity: 0; transform: translateY(var(--end)); } }
.ui-real.m { background: #000; }
.dv-real .dv-phone .status { position: relative; z-index: 2; background: transparent; color: #fff; }
.dv-real .dv-phone .status span { background: #fff; }
.dv-real .dv-phone .screen { background: #000; }

/* selos flutuando em profundidade (3D de verdade: translateZ dentro do rig) */
.rs-chips { position: absolute; inset: 0; transform-style: preserve-3d; pointer-events: none; }
.rs-chips span { position: absolute; display: inline-flex; align-items: center; gap: .45em; white-space: nowrap; font: 600 clamp(.62rem, 1.35vw, .86rem)/1 var(--body); color: #fff; background: rgba(12,16,24,.82); border: 1px solid rgba(192,138,30,.55); border-radius: 99px; padding: .55em .95em; box-shadow: 0 14px 30px -10px rgba(0,0,0,.6); backdrop-filter: none; }
.rs-chips span::before { content: ""; width: .55em; height: .55em; border-radius: 50%; background: #C08A1E; box-shadow: 0 0 0 .25em rgba(192,138,30,.25); }
.rs-chips .c1 { left: -6%; top: 46%; transform: translateZ(140px); }
.rs-chips .c2 { right: 24%; top: -9%; transform: translateZ(90px); }
.rs-chips .c3 { left: 10%; bottom: 8%; transform: translateZ(180px); }
.dv-stack .rs-chips .c1 { left: -2%; top: 4%; } .dv-stack .rs-chips .c2 { right: 2%; top: 30%; } .dv-stack .rs-chips .c3 { left: 6%; bottom: 6%; }
@media (prefers-reduced-motion: no-preference) {
  .rs-chips span { animation: rs-float 7s ease-in-out infinite; }
  .rs-chips .c2 { animation-delay: -2.4s; } .rs-chips .c3 { animation-delay: -4.6s; }
}
@keyframes rs-float { 50% { translate: 0 -8px; } }
.dv-cap { position: absolute; left: 0; right: 0; bottom: -8%; text-align: center; font: 500 .82rem/1.3 var(--body); color: #B9C3D1; letter-spacing: .01em; }
.dv-cap b { color: #F2D69C; font-weight: 600; }
.dv-real .dv-cap b { display: inline-block; }
.dv-real .dv-cap .u2 { margin-left: .4em; }
.dv-real .dv-cap .u1, .dv-real .dv-cap .u2 { animation: none; }
.dv-real .dv-cap .u1::after { content: " e"; color: #B9C3D1; font-weight: 500; }

@media (max-width: 600px) { .dv-stack img { width: 82%; } .dv-stack .st-a { left: 12%; } .dv-stack .st-b { left: 0; } .rs-chips span { font-size: .6rem; } .rs-chips .c2 { display: none; } .dv-cap { bottom: -10%; font-size: .72rem; } }
/* sistema real do Aurora Premium: duas telas que trocam de lugar em profundidade */
.dv-stack { aspect-ratio: 1.25; }
.dv-stack img { position: absolute; width: 92%; height: auto; filter: drop-shadow(0 30px 40px rgba(0,0,0,.55)); }
.dv-stack .st-a { left: 8%; top: 18%; transform: translateZ(60px); animation: st-a 16s cubic-bezier(.6,0,.3,1) infinite; z-index: 2; }
.dv-stack .st-b { left: -6%; top: 0; transform: translateZ(-140px) scale(.9); opacity: .55; animation: st-b 16s cubic-bezier(.6,0,.3,1) infinite; z-index: 1; }
@keyframes st-a { 0%, 42% { transform: translate3d(0,0,60px); opacity: 1; z-index: 2; } 50%, 92% { transform: translate3d(-14%,-18%,-140px) scale(.9); opacity: .55; z-index: 1; } 100% { transform: translate3d(0,0,60px); opacity: 1; z-index: 2; } }
@keyframes st-b { 0%, 42% { transform: translate3d(0,0,-140px) scale(.9); opacity: .55; z-index: 1; } 50%, 92% { transform: translate3d(14%,18%,60px) scale(1); opacity: 1; z-index: 2; } 100% { transform: translate3d(0,0,-140px) scale(.9); opacity: .55; z-index: 1; } }

@media (prefers-reduced-motion: reduce) {
  .dv-rig, .dv-scene *, .dv-scene [style*="--d"] { animation: none !important; opacity: 1 !important; transform: none; }
  .dv-tilt { transition: none; }
  .dv-real .s2, .dv-real .u2 { display: none; } .dv-real .s1 { opacity: 1; transform: none; } .dv-stack img { animation: none; }
  .ui-compose .typed { clip-path: none; } .ui-compose .sent { opacity: 1; } .ui-kanban .mover { display: none; }
  .ui-serp .me { top: 0; } .ui-serp .r0 { top: 20%; } .ui-serp .r1 { top: 40%; } .ui-serp .r2 { top: 60%; } .ui-serp .r3 { top: 80%; }
}

/* ---------- APARELHOS REALISTAS (27/10/2026): arte criada pela Viviane + interface real encaixada na tela (devices.js) */
.dv-scene.rx-scene { aspect-ratio: auto; perspective: none; contain: layout style; }
.dv-scene.rx-scene.solo { max-width: 340px; }
.rx { position: relative; width: 100%; }
@keyframes rx-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-1.2%); } }
.rx .rx-moldura { position: relative; z-index: 2; display: block; width: 100%; height: auto; pointer-events: none; }
.rx .rx-tela { position: absolute; left: 0; top: 0; z-index: 1; transform-origin: 0 0; overflow: hidden; background: #fff; visibility: hidden; }
.rx.rx-ok .rx-tela { visibility: visible; }
.rx .rx-tela.dv-mac, .rx .rx-tela.dv-phone { right: auto; bottom: auto; width: auto; }
.rx .rx-tela .screen { position: relative; width: 100%; height: 100%; aspect-ratio: auto; border-radius: 0; overflow: hidden; container-type: inline-size; }
.rx .rx-P .screen { display: flex; flex-direction: column; }
.rx .rx-O, .rx .rx-T { background: #0B1220; }
.ui-shot { position: absolute; inset: 0; background: #fff; } .ui-shot img { width: 100%; height: 100%; object-fit: cover; object-position: top left; display: block; }
.ui-real .vp .solo-s { opacity: 1 !important; animation: rx-rola 16s cubic-bezier(.45,.05,.35,1) 1s infinite alternate !important; }
@keyframes rx-rola { 0%, 8% { transform: translateY(0); } 92%, 100% { transform: translateY(calc(-100% + 844px)); } }
.rx-scene .dv-cap { bottom: -4%; }
@media (prefers-reduced-motion: reduce) { .rx { animation: none; } }
/* ---------- software sob medida (v6): um sistema que conecta as áreas da empresa. Um pedido de exemplo passa por
   Marketing, Comercial, Suprimentos, Operações, Pessoas, Financeiro, Atendimento e TI; cada área acende na sua vez (ciclo de 16 s). */
.rx .ig, .ig { position: relative; width: 1100px; height: 733px; background: #0B1220; color: #fff; font-family: var(--font-body); overflow: hidden; }
.ig-top { display: flex; align-items: baseline; gap: 16px; height: 66px; padding: 18px 28px 0; border-bottom: 1px solid rgba(255,255,255,.08); }
.ig-top b { font-size: 26px; } .ig-top span { font-size: 19px; color: #C9D1DE; } .ig-top small { margin-left: auto; font-size: 15px; color: #8FA3BF; }
.ig-svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.ig-svg line { stroke: rgba(143,163,191,.35); stroke-width: 2; animation: ig-linha 16s linear infinite; animation-delay: calc(var(--i, 0) * 2s - 16s); }
.ig-svg line.anel { stroke: rgba(192,138,30,.28); stroke-dasharray: 4 8; animation: none; }
.ig-hub { position: absolute; transform: translate(-50%, -50%); width: 150px; height: 150px; border-radius: 50%; display: grid; place-items: center; text-align: center; background: radial-gradient(closest-side, #16233A, #0B1220); border: 2px solid #C08A1E; box-shadow: 0 0 40px rgba(192,138,30,.35); font-size: 21px; font-weight: 700; line-height: 1.2; color: #F2D69C; }
.ig-no { position: absolute; transform: translate(-50%, -50%); padding: 10px 18px; border-radius: 999px; background: #16233A; border: 2px solid rgba(192,138,30,.55); font-size: 21px; font-weight: 700; white-space: nowrap; animation: ig-no 16s linear infinite; animation-delay: calc(var(--i) * 2s - 16s); }
.ig-passos { position: absolute; left: 640px; top: 90px; right: 26px; margin: 0; padding: 0; list-style: none; display: grid; gap: 8px; }
.ig-passos li { padding: 9px 16px; border-radius: 10px; background: rgba(255,255,255,.04); border-left: 4px solid rgba(192,138,30,.3); animation: ig-passo 16s linear infinite; animation-delay: calc(var(--i) * 2s - 16s); }
.ig-passos b { display: block; font-size: 19px; } .ig-passos span { font-size: 17px; color: #C9D1DE; }
@keyframes ig-no { 0%, 11% { background: #C08A1E; color: #000; border-color: #F2D69C; box-shadow: 0 0 28px rgba(192,138,30,.8); } 13%, 100% { background: #16233A; color: #fff; border-color: rgba(192,138,30,.55); box-shadow: none; } }
@keyframes ig-linha { 0%, 11% { stroke: #C08A1E; stroke-width: 5; } 13%, 100% { stroke: rgba(143,163,191,.35); stroke-width: 2; } }
@keyframes ig-passo { 0%, 11% { background: rgba(192,138,30,.22); border-left-color: #C08A1E; } 13%, 100% { background: rgba(255,255,255,.04); border-left-color: rgba(192,138,30,.3); } }
/* painel por área (tablet) */
.ig-painel { height: 800px; }
.ig-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; padding: 20px 26px; }
.ig-card { position: relative; padding: 16px 20px; border-radius: 14px; background: #16233A; border: 2px solid rgba(192,138,30,.25); animation: ig-card 16s linear infinite; animation-delay: calc(var(--i) * 2s - 16s); }
.ig-card b { display: block; font-size: 22px; color: #F2D69C; } .ig-card strong { display: block; font-size: 40px; line-height: 1.15; } .ig-card span { font-size: 18px; color: #C9D1DE; }
.ig-card i { position: absolute; right: 16px; top: 18px; font-style: normal; font-size: 15px; color: #7FD1A8; }
@keyframes ig-card { 0%, 11% { border-color: #C08A1E; box-shadow: 0 0 26px rgba(192,138,30,.55); } 13%, 100% { border-color: rgba(192,138,30,.25); box-shadow: none; } }
/* feed do pedido (celular) */
.ig-feed { width: 390px; height: 844px; padding-top: 44px; }
.ig-feed .ig-top { height: auto; padding: 14px 20px 12px; flex-wrap: wrap; } .ig-feed .ig-top b { font-size: 22px; }
.ig-feed ol { margin: 0; padding: 14px 16px; list-style: none; display: grid; gap: 9px; }
.ig-feed li { padding: 11px 14px; border-radius: 12px; background: #16233A; border-left: 4px solid rgba(192,138,30,.3); animation: ig-passo 16s linear infinite; animation-delay: calc(var(--i) * 2s - 16s); }
.ig-feed li b { display: block; font-size: 17px; color: #F2D69C; } .ig-feed li span { font-size: 15.5px; color: #C9D1DE; }

