.dv-rig { position: absolute; inset: 0; transform-style: preserve-3d; animation: dv-sway 22s ease-in-out infinite; }
@keyframes dv-sway { 0%, 100% { transform: rotateY(-5deg) translateY(0); } 50% { transform: rotateY(6deg) translateY(-1.2%); } }
.dv-floor { position: absolute; left: 8%; right: 8%; bottom: -2%; height: 14%; background: radial-gradient(50% 50% at 50% 50%, rgba(192,138,30,.28), rgba(192,138,30,0) 70%); filter: blur(8px); z-index: -1; pointer-events: none; }
.dv-photo img { width: 100%; height: auto; display: block; filter: drop-shadow(0 30px 40px rgba(0,0,0,.55)); }

/* ---------- notebook (estilo alumínio, sem logo) */
.dv-mac { position: absolute; left: 0; top: 3%; width: 86%; transform: translateZ(0); }
.focus-phone .dv-mac { width: 74%; top: 8%; filter: brightness(.82); }
.dv-mac .lid { background: linear-gradient(180deg, #e3e6ea, #b8bdc5); border-radius: 16px 16px 5px 5px; padding: 1.4%; box-shadow: 0 1px 0 rgba(255,255,255,.6) inset, 0 40px 70px -20px rgba(0,0,0,.7); }
.dv-mac .bezel { position: relative; background: #08090b; border-radius: 11px 11px 3px 3px; padding: 2.2% 1.8% 2.6%; }
.dv-mac .cam { position: absolute; left: 50%; top: .9%; width: 1.1%; aspect-ratio: 1; border-radius: 50%; background: #1d2b3f; transform: translateX(-50%); }
.dv-mac .screen { position: relative; aspect-ratio: 16 / 10; overflow: hidden; border-radius: 3px; background: #fff; container-type: inline-size; }
.dv-mac .base { position: relative; width: 114%; margin-left: -7%; aspect-ratio: 46 / 1; background: linear-gradient(180deg, #eef0f3 0%, #c4c8cf 55%, #9ba1aa 100%); border-radius: 2px 2px 14px 14px / 2px 2px 60px 60px; box-shadow: 0 18px 30px -8px rgba(0,0,0,.6); }
.dv-mac .base i { position: absolute; left: 50%; top: 0; width: 15%; height: 45%; transform: translateX(-50%); background: linear-gradient(180deg, #aeb3bb, #d3d6db); border-radius: 0 0 8px 8px; }

/* ---------- celular (bordas finas, ilha no topo, sem logo) */
.dv-phone { position: absolute; right: 0; bottom: 0; width: 27%; transform: translateZ(60px); }
.focus-phone .dv-phone { width: 36%; right: 4%; bottom: 0; }
.solo .dv-phone { position: relative; width: 78%; margin: 4% auto 0; transform: none; right: auto; }
.dv-phone .frame { aspect-ratio: 9 / 19.3; background: #111317; border-radius: 15% / 7.2%; padding: 3.6%; box-shadow: 0 0 0 1.5px #9ea3ab, 0 0 0 3px #d9dce0, 0 40px 60px -15px rgba(0,0,0,.75); }
.dv-phone .screen { position: relative; height: 100%; overflow: hidden; border-radius: 12% / 5.6%; background: #fff; container-type: inline-size; display: flex; flex-direction: column; }
.dv-phone .island { position: absolute; z-index: 3; left: 50%; top: 2.2%; width: 32%; height: 3.4%; transform: translateX(-50%); background: #000; border-radius: 99px; }
.dv-phone .status { flex: none; height: 7.5%; display: flex; align-items: center; justify-content: space-between; padding: 0 9%; font: 600 5cqw/1 var(--body); color: #111; }
.dv-phone .status span { width: 14%; height: 30%; border-radius: 2px; background: #111; }

/* ---------- peças que entram em sequência (atraso em --d), saem e voltam: o sistema "subindo" */
.dv [style*="--d"], .dv-scene [style*="--d"] { animation: dv-in var(--cyc) var(--d) infinite both; }
@keyframes dv-in { 0% { opacity: 0; transform: translateY(8px); } 5% { opacity: 1; transform: none; } 86% { opacity: 1; transform: none; } 93%, 100% { opacity: 0; transform: none; } }
.dv-paused * { animation-play-state: paused !important; }

.ui { position: absolute; inset: 0; font-family: var(--body); color: #16233A; }
.dv-phone .ui { position: relative; inset: auto; flex: 1; min-height: 0; }
.ui .ln { display: block; height: 1.1cqw; border-radius: 99px; background: #DCE2EA; margin: .9cqw 0; }
.ui b, .ui strong { font-weight: 700; }

/* painel (sistema sob medida) */
.ui-dash { display: grid; grid-template-columns: 15% 1fr; background: #F4F6F9; }
.ui-dash aside, .ui-inbox aside { background: #16233A; padding: 3cqw 2cqw; display: flex; flex-direction: column; gap: 1.8cqw; }
.ui-dash .logo, .ui-inbox .logo { width: 4cqw; aspect-ratio: 1; border-radius: 1cqw; background: #C08A1E; margin-bottom: 1.5cqw; }
.ui-dash .nav, .ui-inbox .nav { height: 1.3cqw; border-radius: 99px; background: rgba(255,255,255,.22); }
.ui-dash .nav.on, .ui-inbox .nav.on { background: #C08A1E; }
.ui-dash .ui-main { padding: 2.6cqw 3cqw; display: grid; grid-template-rows: auto auto 1fr auto; gap: 2cqw; min-width: 0; }
.ui-dash header, .ui-inbox header { display: flex; align-items: center; gap: 1.6cqw; }
.ui-dash header b, .ui-inbox header b { font-size: 2.6cqw; }
.ui-dash header small, .ui-inbox header small { font-size: 1.5cqw; color: #8A5C00; background: #FBF3E2; padding: .4cqw 1cqw; border-radius: 99px; }
.ui-dash header .av { margin-left: auto; width: 3.4cqw; aspect-ratio: 1; border-radius: 50%; background: #C9D1DC; }
.ui-dash .kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.6cqw; }
.ui-dash .kpi { background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.6cqw 2cqw; display: grid; gap: .5cqw; }
.ui-dash .kpi small { font-size: 1.5cqw; color: #5A6578; }
.ui-dash .kpi b { font-size: 3.4cqw; line-height: 1; }
.ui-dash .kpi.g { background: #16233A; color: #fff; border-color: #16233A; }
.ui-dash .kpi.g small { color: #B9C3D1; }
.ui-dash .chart { background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.6cqw 2cqw; display: grid; grid-template-rows: auto 1fr; min-height: 0; }
.ui-dash .chart small { font-size: 1.5cqw; color: #5A6578; }
.ui-dash .bars { display: flex; align-items: flex-end; gap: 1.6cqw; padding-top: 1.4cqw; min-height: 0; }
.ui-dash .bars i { flex: 1; height: var(--h); background: linear-gradient(180deg, #C08A1E, #A87000); border-radius: .8cqw .8cqw 0 0; transform-origin: bottom; animation: dv-bar var(--cyc) var(--d) infinite both !important; }
.ui-dash .bars i:nth-child(odd) { background: #2D4466; }
@keyframes dv-bar { 0% { transform: scaleY(0); } 6% { transform: scaleY(1); } 86% { transform: scaleY(1); } 93%, 100% { transform: scaleY(0); } }
.ui-dash .table { display: grid; grid-template-columns: 1.3fr 1fr 1fr; gap: .2cqw 0; font-size: 1.5cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.2cqw 2cqw; }
.ui-dash .table em { font-style: normal; color: #5A6578; padding-bottom: .6cqw; border-bottom: 1px solid #E3E8EF; }
.ui-dash .tr { display: contents; }
.ui-dash .tr > span { padding: .7cqw 0; border-bottom: 1px solid #F0F3F7; }
.ui-dash .tr .tag { justify-self: start; color: #8A5C00; }

/* aplicativo (celular) */
.ui-app { background: #F4F6F9; padding: 4cqw 6cqw 0; display: flex; flex-direction: column; gap: 4cqw; }
.ui-app header small { display: block; font-size: 6cqw; color: #5A6578; }
.ui-app header b { font-size: 9.5cqw; line-height: 1.1; }
.ui-app .card { display: flex; gap: 4cqw; align-items: center; background: #fff; border-radius: 5cqw; padding: 4.5cqw 5cqw; box-shadow: 0 1px 0 #E3E8EF; border-left: 2.2cqw solid #C08A1E; }
.ui-app .card:nth-of-type(even) { border-left-color: #2D4466; }
.ui-app .card > b { font-size: 6.5cqw; }
.ui-app .card span { display: grid; }
.ui-app .card strong { font-size: 6.5cqw; }
.ui-app .card small { font-size: 5.5cqw; color: #5A6578; }
.ui-app .toast { position: absolute; left: 4cqw; right: 4cqw; top: 3cqw; z-index: 2; display: flex; gap: 4cqw; align-items: center; background: rgba(22,35,58,.94); color: #fff; border-radius: 6cqw; padding: 4.5cqw 5cqw; box-shadow: 0 12px 24px rgba(0,0,0,.25); }
.ui-app .toast i { width: 9cqw; aspect-ratio: 1; border-radius: 2.5cqw; background: #C08A1E; flex: none; }
.ui-app .toast span { display: grid; }
.ui-app .toast strong { font-size: 6cqw; }
.ui-app .toast small { font-size: 5.2cqw; color: #C9D1DC; }
.ui-app nav { margin-top: auto; display: flex; justify-content: space-around; padding: 4cqw 0 7cqw; background: #fff; margin-left: -6cqw; margin-right: -6cqw; }
.ui-app nav i { width: 8cqw; aspect-ratio: 1; border-radius: 2cqw; background: #C9D1DC; }
.ui-app nav i.on { background: #C08A1E; }

/* navegador e site */
.ui-browser, .ui-serp { display: flex; flex-direction: column; background: #fff; }
.ui .bar { flex: none; display: flex; align-items: center; gap: .9cqw; padding: 1.3cqw 1.8cqw; background: #EDEFF2; border-bottom: 1px solid #DDE1E6; }
.ui .bar > i { width: 1.3cqw; aspect-ratio: 1; border-radius: 50%; background: #C7CCD3; }
.ui .bar span { margin-left: 2cqw; flex: 1; max-width: 50%; font-size: 1.6cqw; color: #5A6578; background: #fff; border-radius: 99px; padding: .5cqw 2cqw; }
.ui-browser .site { flex: 1; padding: 0 4cqw; display: grid; grid-template-rows: auto 1fr auto; }
.ui-browser .nav { display: flex; align-items: center; gap: 2.4cqw; padding: 2cqw 0; border-bottom: 1px solid #EEF1F5; }
.ui-browser .nav .logo { width: 10cqw; height: 2.4cqw; border-radius: 99px; background: #16233A; margin-right: auto; }
.ui-browser .nav .ln { margin: 0; }
.ui-browser .nav .cta { width: 10cqw; height: 3cqw; border-radius: 99px; background: #C08A1E; }
.ui-browser .hero { display: grid; grid-template-columns: 1.1fr 1fr; gap: 3cqw; align-items: center; padding: 3cqw 0; }
.ui-browser .hero b { display: block; font: 700 4.2cqw/1.1 var(--display); letter-spacing: -.02em; }
.ui-browser .hero .ln { height: 1.2cqw; }
.ui-browser .btn, .ui-msite .btn { display: inline-flex; margin-top: 1.6cqw; font-style: normal; font-weight: 700; font-size: 1.7cqw; color: #fff; background: #1F7A55; border-radius: 99px; padding: 1.1cqw 2.6cqw; }
.ui-browser .hero .img { display: block; aspect-ratio: 4/3; border-radius: 2cqw; background: linear-gradient(135deg, #16233A, #2D4466 60%, #C08A1E); }
.ui-browser .cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2cqw; padding-bottom: 3cqw; }
.ui-browser .col { border: 1px solid #E3E8EF; border-radius: 1.6cqw; padding: 1.8cqw; }
.ui-browser .col .ic { display: block; width: 3.6cqw; aspect-ratio: 1; border-radius: 1cqw; background: #FBF3E2; border: 1px solid #C08A1E; }
.ui-msite { background: #fff; padding: 3cqw 7cqw; display: flex; flex-direction: column; gap: 4cqw; }
.ui-msite .mnav { display: flex; justify-content: space-between; align-items: center; }
.ui-msite .logo { width: 30cqw; height: 6cqw; border-radius: 99px; background: #16233A; }
.ui-msite .burger { width: 8cqw; height: 6cqw; border-top: 1.4cqw solid #16233A; border-bottom: 1.4cqw solid #16233A; }
.ui-msite > b { font: 700 11cqw/1.08 var(--display); letter-spacing: -.02em; }
.ui-msite .ln { height: 3cqw; margin: 2.4cqw 0; }
.ui-msite .btn { font-size: 6.5cqw; padding: 4cqw 7cqw; justify-content: center; margin-top: 0; }
.ui-msite .img { display: block; aspect-ratio: 4/3; border-radius: 5cqw; background: linear-gradient(135deg, #16233A, #2D4466 60%, #C08A1E); }
.ui-msite .wa { position: absolute; right: 6cqw; bottom: 8cqw; width: 18cqw; aspect-ratio: 1; border-radius: 50%; background: #1F7A55; box-shadow: 0 8px 16px rgba(0,0,0,.25); }

/* resultados de busca: o site do cliente sobe até o primeiro lugar */
.ui-serp .q { margin: 2.4cqw 4cqw 1.4cqw; display: flex; align-items: center; gap: 1.6cqw; font-size: 2cqw; border: 1px solid #DDE1E6; border-radius: 99px; padding: 1.3cqw 2.6cqw; box-shadow: 0 2px 6px rgba(0,0,0,.06); }
.ui-serp .mg, .ui-mserp .mg { width: 2cqw; aspect-ratio: 1; border-radius: 50%; border: .45cqw solid #5A6578; flex: none; }
.ui-serp .res { position: relative; flex: 1; margin: 0 4cqw 2cqw; animation: dv-fade var(--cyc) infinite both; }
.ui-serp .r { position: absolute; left: 0; right: 0; height: 18%; padding: 1cqw 1.6cqw; border-radius: 1.4cqw; display: grid; align-content: center; gap: .3cqw; }
.ui-serp .r small { font-size: 1.4cqw; color: #5A6578; }
.ui-serp .r b { display: block; font-size: 1.9cqw; line-height: 1.3; color: #1A0DAB; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ui-serp .r small { display: block; line-height: 1.2; }
.ui-serp .r span { font-size: 1.45cqw; color: #4D5156; line-height: 1.35; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.ui-serp .me { background: #FBF3E2; box-shadow: 0 0 0 2px #C08A1E; z-index: 2; }
.ui-serp .me b { font-size: 1.9cqw; color: #16233A; }
.ui-serp .me small { color: #8A5C00; font-weight: 700; }
.ui-serp .r0 { animation: dv-r0 var(--cyc) infinite; } .ui-serp .r1 { animation: dv-r1 var(--cyc) infinite; }
.ui-serp .r2 { animation: dv-r2 var(--cyc) infinite; } .ui-serp .r3 { animation: dv-r3 var(--cyc) infinite; }
.ui-serp .me { animation: dv-me var(--cyc) infinite; }
@keyframes dv-fade { 0% { opacity: 0; } 4%, 92% { opacity: 1; } 97%, 100% { opacity: 0; } }
@keyframes dv-me { 0%, 14% { top: 80%; } 22%, 32% { top: 60%; } 40%, 50% { top: 40%; } 58%, 68% { top: 20%; } 76%, 98% { top: 0%; } 100% { top: 80%; } }
@keyframes dv-r3 { 0%, 14% { top: 60%; } 22%, 98% { top: 80%; } 100% { top: 60%; } }
@keyframes dv-r2 { 0%, 32% { top: 40%; } 40%, 98% { top: 60%; } 100% { top: 40%; } }
@keyframes dv-r1 { 0%, 50% { top: 20%; } 58%, 98% { top: 40%; } 100% { top: 20%; } }
@keyframes dv-r0 { 0%, 68% { top: 0%; } 76%, 98% { top: 20%; } 100% { top: 0%; } }
.ui-mserp { background: #fff; padding: 3cqw 6cqw; display: flex; flex-direction: column; gap: 4cqw; }
.ui-mserp .q { display: flex; align-items: center; gap: 3cqw; font-size: 6cqw; border: 1px solid #DDE1E6; border-radius: 99px; padding: 3.5cqw 5cqw; }
.ui-mserp .mg { width: 5cqw; border-width: 1.1cqw; }
.ui-mserp .map { position: relative; aspect-ratio: 16/10; border-radius: 4cqw; background: linear-gradient(90deg, rgba(255,255,255,.6) 1px, transparent 1px) 0 0/22% 100%, linear-gradient(rgba(255,255,255,.6) 1px, transparent 1px) 0 0/100% 30%, #E7ECE4; }
.ui-mserp .pin { position: absolute; left: 46%; top: 30%; width: 9cqw; aspect-ratio: 1; border-radius: 50% 50% 50% 0; transform: rotate(-45deg); background: #C08A1E; box-shadow: 0 0 0 2cqw rgba(192,138,30,.25); }
.ui-mserp .me { border-radius: 4cqw; padding: 4cqw; background: #FBF3E2; box-shadow: 0 0 0 1.5px #C08A1E; display: grid; gap: 1.5cqw; }
.ui-mserp .me b { font-size: 7.5cqw; }
.ui-mserp .me small { font-size: 5.5cqw; color: #5A6578; }
.ui-mserp .me span { display: flex; gap: 2cqw; }
.ui-mserp .me span i { font-style: normal; font-size: 5cqw; font-weight: 700; color: #8A5C00; border: 1px solid #C08A1E; border-radius: 99px; padding: 1.6cqw 3cqw; }
.ui-mserp .ln { height: 3cqw; margin: 2.4cqw 0; }

/* assistente de IA */
.ui-ai { display: grid; grid-template-columns: 17% 1fr; background: #fff; }
.ui-ai aside { background: #F4F6F9; padding: 3cqw 2cqw; display: flex; flex-direction: column; gap: 1.8cqw; }
.ui-ai aside .nb { height: 3cqw; border-radius: 1cqw; background: #16233A; margin-bottom: 1.5cqw; }
.ui-ai .ui-main { position: relative; padding: 4cqw 7cqw; display: flex; flex-direction: column; gap: 3cqw; }
.ui-ai .u, .ui-mai .u { align-self: flex-end; max-width: 75%; background: #EEF1F5; border-radius: 2.4cqw 2.4cqw .6cqw 2.4cqw; padding: 1.6cqw 2.4cqw; font-size: 2cqw; }
.ui-ai .a { display: grid; grid-template-columns: auto 1fr; gap: 2cqw; }
.ui-ai .spark { width: 3.4cqw; aspect-ratio: 1; border-radius: 1cqw; background: conic-gradient(from 45deg, #C08A1E, #16233A, #C08A1E); }
.ui-ai .a .txt { margin: 0 0 1.4cqw; font-size: 1.85cqw; line-height: 1.45; color: #16233A; }
.ui-ai .a .txt b { color: #8A5C00; }
.ui-ai .src, .ui-mai .me { display: flex; flex-wrap: wrap; gap: 1.2cqw; align-items: center; margin-top: 1.6cqw; }
.ui-ai .src small { font-size: 1.5cqw; color: #5A6578; }
.ui-ai .src span { font-size: 1.6cqw; padding: .6cqw 1.6cqw; border-radius: 99px; border: 1px solid #DDE1E6; color: #5A6578; }
.ui-ai .src .me { border-color: #C08A1E; background: #FBF3E2; color: #8A5C00; font-weight: 700; }
.ui-ai .input { position: absolute; left: 7cqw; right: 7cqw; bottom: 3cqw; height: 5cqw; border: 1px solid #DDE1E6; border-radius: 99px; }
.ui-mai { background: #fff; padding: 4cqw 6cqw; display: flex; flex-direction: column; gap: 4cqw; }
.ui-mai .u { font-size: 6cqw; border-radius: 6cqw 6cqw 1.5cqw 6cqw; padding: 4cqw 5cqw; }
.ui-mai .a .txt { margin: 0 0 3cqw; font-size: 5.6cqw; line-height: 1.4; color: #16233A; }
.ui-mai .a .txt b { color: #8A5C00; }
.ui-mai .me { display: inline-flex; font-size: 5.6cqw; font-weight: 700; color: #8A5C00; background: #FBF3E2; border: 1px solid #C08A1E; border-radius: 99px; padding: 2.4cqw 4cqw; }

/* conversa (agente de IA no WhatsApp) */
.ui-chat { display: flex; flex-direction: column; background: #ECE5DD; }
.ui-chat header { display: flex; align-items: center; gap: 4cqw; padding: 3cqw 5cqw 4cqw; background: #0E5A4A; color: #fff; }
.ui-chat header .av { width: 12cqw; aspect-ratio: 1; border-radius: 50%; background: #C08A1E; }
.ui-chat header span { display: grid; }
.ui-chat header b { font-size: 6.5cqw; }
.ui-chat header small { font-size: 5cqw; color: #CDE7DF; }
.ui-chat .msgs { flex: 1; display: flex; flex-direction: column; gap: 3cqw; padding: 5cqw 4cqw; }
.ui-chat p { margin: 0; max-width: 82%; padding: 3cqw 4cqw; font-size: 5.8cqw; line-height: 1.3; border-radius: 4cqw; box-shadow: 0 1px 0 rgba(0,0,0,.08); position: relative; color: #16233A; }
.ui-chat .in { align-self: flex-start; background: #fff; border-top-left-radius: 1cqw; }
.ui-chat .out { align-self: flex-end; background: #DCF8C6; border-top-right-radius: 1cqw; padding-right: 9cqw; }
.ui-chat .out i { position: absolute; right: 2.5cqw; bottom: 2.4cqw; width: 5cqw; color: #34B7F1; }
.ui-chat .out i svg { width: 100%; height: auto; display: block; }
.ui-chat .typing { align-self: flex-start; background: #fff; display: flex; gap: 1.6cqw; padding: 3.6cqw 4.5cqw; }
.ui-chat .typing i { width: 2.4cqw; aspect-ratio: 1; border-radius: 50%; background: #9AA4B2; }
.ui-chat .input { margin: 0 4cqw 7cqw; height: 11cqw; border-radius: 99px; background: #fff; }

/* caixa de conversas (notebook) */
.ui-inbox { display: grid; grid-template-columns: 15% 1fr; background: #F4F6F9; }
.ui-inbox .ui-main { padding: 3cqw; display: flex; flex-direction: column; gap: 1.6cqw; }
.ui-inbox .conv { display: flex; align-items: center; gap: 2cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.6cqw 2cqw; }
.ui-inbox .conv .av { width: 4cqw; aspect-ratio: 1; border-radius: 50%; background: #C9D1DC; flex: none; }
.ui-inbox .conv span { display: grid; flex: 1; min-width: 0; }
.ui-inbox .conv b { font-size: 1.9cqw; }
.ui-inbox .conv small { font-size: 1.6cqw; color: #5A6578; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ui-inbox .conv em { font-style: normal; font-size: 1.5cqw; font-weight: 700; padding: .5cqw 1.4cqw; border-radius: 99px; }
.ui-inbox .conv em.ok { background: #E3F2EC; color: #1F7A55; }
.ui-inbox .conv em.hu { background: #FBF3E2; color: #8A5C00; }


/* ===================== telas novas (26/10/2026) ===================== */
.ui-chat .msgs { justify-content: flex-end; overflow: hidden; }
.ui-chat .intent, .ui-chat .src { align-self: center; max-width: none; box-shadow: none; padding: 1.4cqw 3.4cqw; font-size: 4.4cqw; font-weight: 700; border-radius: 99px; }
.ui-chat .intent { background: #16233A; color: #F2D69C; }
.ui-chat .src { background: rgba(255,255,255,.7); color: #5A6578; font-weight: 600; }
/* texto das bolhas: cor própria, sem herdar o branco da seção escura (contraste) */
.ui.ui-chat p { color: #16233A; }
.ui.ui-chat p.src, .ui.ui-chat p.src small { color: #5A6578; }
.ui-eng p:not(.intent):not(.src) { font-size: 5.4cqw; }
.ui-compose .av.rq { background: #000 url(/img/roque-simbolo.png) center/70% no-repeat; }
.ui-compose .msgs { justify-content: flex-end; }
.ui-compose .sent { opacity: 0; animation: dv-sent 9s infinite both; }
.ui-compose .input { display: flex; align-items: center; gap: 3cqw; height: auto; min-height: 11cqw; padding: 2.4cqw 3cqw 2.4cqw 5cqw; border-radius: 6cqw; }
.ui-compose .typed { flex: 1; font-size: 5.2cqw; line-height: 1.3; color: #16233A; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; clip-path: inset(0 100% 0 0); animation: dv-type 9s steps(28) infinite both; }
.ui-compose .send { flex: none; width: 9cqw; aspect-ratio: 1; border-radius: 50%; background: #1F7A55; }
@keyframes dv-type { 0% { clip-path: inset(0 100% 100% 0); opacity: 1; } 45% { clip-path: inset(0 0 0 0); opacity: 1; } 55% { clip-path: inset(0 0 0 0); opacity: 1; } 58%, 100% { opacity: 0; } }
@keyframes dv-sent { 0%, 57% { opacity: 0; transform: translateY(6px); } 62%, 94% { opacity: 1; transform: none; } 100% { opacity: 0; } }

/* chat no site */
.ui-webchat { position: absolute; }
.ui-webchat .wc { position: absolute; right: 3cqw; bottom: 9cqw; width: 34cqw; background: #fff; border-radius: 1.8cqw; box-shadow: 0 2cqw 5cqw rgba(22,35,58,.28); padding: 0 0 1.6cqw; display: flex; flex-direction: column; gap: 1cqw; overflow: hidden; }
.ui-webchat .wc header { display: flex; align-items: center; gap: 1.2cqw; background: #16233A; color: #fff; padding: 1.4cqw 1.8cqw; }
.ui-webchat .wc header .av { width: 2.8cqw; aspect-ratio: 1; border-radius: 50%; background: #C08A1E; }
.ui-webchat .wc header b { font-size: 1.7cqw; }
.ui-webchat .wc header small { margin-left: auto; font-size: 1.3cqw; color: #F2D69C; }
.ui-webchat .wc p { margin: 0 1.6cqw; padding: 1cqw 1.4cqw; font-size: 1.55cqw; line-height: 1.3; border-radius: 1.2cqw; max-width: 82%; }
.ui-webchat .wc .in { align-self: flex-start; background: #EEF1F5; }
.ui-webchat .wc .out { align-self: flex-end; background: #FBF3E2; color: #16233A; }
.ui-webchat .wc .intent { align-self: center; background: #16233A; color: #F2D69C; font-weight: 700; font-size: 1.25cqw; border-radius: 99px; padding: .5cqw 1.4cqw; }
.ui-webchat .wc .field { display: block; margin: .4cqw 1.6cqw 0; height: 3cqw; border: 1px solid #DDE1E6; border-radius: 99px; }
.ui-webchat .launcher { position: absolute; right: 3cqw; bottom: 2.4cqw; width: 5cqw; aspect-ratio: 1; border-radius: 50%; background: #16233A; box-shadow: 0 1cqw 2cqw rgba(0,0,0,.25); }

/* caixa de conversas do EngageBot: canal de cada conversa */
.ui-inbox .conv .ch { font-style: normal; font-size: 1.2cqw; font-weight: 700; padding: .2cqw .9cqw; border-radius: 99px; margin-left: .6cqw; vertical-align: middle; }
.ui-inbox .conv .ch.wa { background: #E3F2EC; color: #1F7A55; }
.ui-inbox .conv .ch.web { background: #E7ECF4; color: #2D4466; }

/* base de conhecimento */
.ui-kb, .ui-audit, .ui-tickets { display: grid; grid-template-columns: 15% 1fr; background: #F4F6F9; }
.ui-kb aside, .ui-audit aside, .ui-tickets aside { background: #16233A; padding: 3cqw 2cqw; display: flex; flex-direction: column; gap: 1.8cqw; }
.ui-kb .logo, .ui-audit .logo, .ui-tickets .logo { width: 4cqw; aspect-ratio: 1; border-radius: 1cqw; background: #C08A1E; margin-bottom: 1.5cqw; }
.ui-kb .nav, .ui-audit .nav, .ui-tickets .nav { height: 1.3cqw; border-radius: 99px; background: rgba(255,255,255,.22); }
.ui-kb .nav.on, .ui-audit .nav.on, .ui-tickets .nav.on { background: #C08A1E; }
.ui-kb .ui-main, .ui-audit .ui-main, .ui-tickets .ui-main { padding: 3cqw; display: flex; flex-direction: column; gap: 1.5cqw; min-width: 0; }
.ui-kb header, .ui-audit header, .ui-tickets header { display: flex; align-items: center; gap: 1.6cqw; }
.ui-kb header b, .ui-audit header b, .ui-tickets header b { font-size: 2.6cqw; }
.ui-kb header small, .ui-audit header small, .ui-tickets header small { font-size: 1.5cqw; color: #8A5C00; background: #FBF3E2; padding: .4cqw 1cqw; border-radius: 99px; }
.ui-kb .src { position: relative; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: .6cqw 2cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.4cqw 2cqw 2cqw; }
.ui-kb .src .ic { font-style: normal; display: grid; place-items: center; width: 4.6cqw; aspect-ratio: 1; border-radius: 1cqw; background: #FBF3E2; color: #8A5C00; font-size: 1.3cqw; font-weight: 700; }
.ui-kb .src .ic.site { background: #E7ECF4; color: #2D4466; }
.ui-kb .src span { display: grid; min-width: 0; }
.ui-kb .src b { font-size: 1.8cqw; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ui-kb .src small { font-size: 1.4cqw; color: #5A6578; }
.ui-kb .src em { font-style: normal; font-size: 1.4cqw; font-weight: 700; color: #1F7A55; background: #E3F2EC; padding: .4cqw 1.2cqw; border-radius: 99px; }
.ui-kb .src .bar { position: absolute; left: 2cqw; right: 2cqw; bottom: .8cqw; height: .5cqw; border-radius: 99px; background: #C08A1E; transform-origin: left; animation: dv-grow var(--cyc) var(--d) infinite both !important; padding: 0; border: 0; }
@keyframes dv-grow { 0% { transform: scaleX(0); } 8% { transform: scaleX(1); } 86% { transform: scaleX(1); } 93%, 100% { transform: scaleX(0); } }
.ui-kb .ask { margin-top: auto; background: #16233A; color: #fff; border-radius: 1.4cqw; padding: 1.6cqw 2cqw; display: grid; gap: .4cqw; }
.ui-kb .ask small { font-size: 1.3cqw; color: #F2D69C; }
.ui-kb .ask b { font-size: 1.8cqw; }
.ui-kb .ask span { font-size: 1.6cqw; color: #C9D1DC; }

/* ativação guiada (celular) */
.ui-act { background: #F4F6F9; padding: 5cqw 6cqw; display: flex; flex-direction: column; gap: 3.6cqw; }
.ui-act header small { display: block; font-size: 5.4cqw; color: #8A5C00; font-weight: 700; }
.ui-act header b { font-size: 8.6cqw; line-height: 1.1; }
.ui-act .st { display: flex; align-items: center; gap: 4cqw; background: #fff; border-radius: 4.5cqw; padding: 4cqw 4.5cqw; box-shadow: 0 1px 0 #E3E8EF; }
.ui-act .st > i { flex: none; display: grid; place-items: center; width: 10cqw; aspect-ratio: 1; border-radius: 50%; background: #1F7A55; color: #fff; font-style: normal; font-weight: 700; font-size: 5cqw; }
.ui-act .st > i svg { width: 60%; }
.ui-act .st.now > i { background: #C08A1E; color: #000; }
.ui-act .st span { display: grid; }
.ui-act .st strong { font-size: 5.6cqw; }
.ui-act .st small { font-size: 4.6cqw; color: #5A6578; }
.ui-act .go { margin-top: auto; margin-bottom: 6cqw; font-style: normal; text-align: center; font-weight: 700; font-size: 6cqw; background: #16233A; color: #fff; border-radius: 99px; padding: 4.4cqw; }

/* CRM: funil em colunas, um cartão atravessa as etapas */
.ui-kanban, .ui-flow, .ui-course, .ui-kw, .ui-editor, .ui-brand, .ui-road { display: flex; flex-direction: column; background: #F4F6F9; }
.ui .tag { position: absolute; right: 3cqw; top: 1.6cqw; font-size: 1.4cqw; color: #8A5C00; background: #FBF3E2; padding: .4cqw 1cqw; border-radius: 99px; z-index: 2; }
.ui-kanban .board { position: relative; flex: 1; display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.8cqw; padding: 5cqw 2.6cqw 2.6cqw; }
.ui-kanban .col { background: #E9EDF3; border-radius: 1.4cqw; padding: 1.4cqw; display: flex; flex-direction: column; gap: 1.2cqw; }
.ui-kanban .col > b { font-size: 1.6cqw; color: #3A4558; }
.ui-kanban .card { background: #fff; border-radius: 1cqw; padding: 1.2cqw 1.4cqw; box-shadow: 0 1px 0 #D8DDE5; display: grid; }
.ui-kanban .card strong { font-size: 1.6cqw; }
.ui-kanban .card .ln { height: .9cqw; margin: .8cqw 0 0; }
.ui-kanban .mover { position: absolute; top: 24cqw; left: 4cqw; width: calc((100% - 5.2cqw - 5.4cqw) / 4 - 2.8cqw); border-left: .8cqw solid #C08A1E; box-shadow: 0 1.4cqw 3cqw rgba(22,35,58,.22); animation: dv-move var(--cyc) infinite both; z-index: 3; }
@keyframes dv-move { 0%, 12% { transform: translateX(0) rotate(0); opacity: 0; } 16% { opacity: 1; } 28%, 36% { transform: translateX(calc(100% + 4.2cqw)) rotate(-2deg); } 50%, 58% { transform: translateX(calc(200% + 8.4cqw)) rotate(1deg); } 72%, 92% { transform: translateX(calc(300% + 12.6cqw)) rotate(0); opacity: 1; } 100% { opacity: 0; transform: translateX(calc(300% + 12.6cqw)); } }

/* automação: blocos ligados, com o dado correndo nos fios */
.ui-flow .canvas { position: relative; flex: 1; background: radial-gradient(#D5DCE6 1px, transparent 1.2px) 0 0 / 3cqw 3cqw; }
.ui-flow .node { position: absolute; width: 24%; background: #fff; border-radius: 1.4cqw; padding: 1.4cqw 1.8cqw; display: grid; gap: .2cqw; box-shadow: 0 1cqw 2.4cqw rgba(22,35,58,.14); border-top: .6cqw solid #C08A1E; z-index: 1; }
.ui-flow .node:nth-child(odd) { border-top-color: #2D4466; }
.ui-flow .node b { font-size: 1.8cqw; }
.ui-flow .node small { font-size: 1.4cqw; color: #5A6578; }
.ui-flow .wires { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.ui-flow .wires path { fill: none; stroke: #9DAAC0; stroke-width: .35; stroke-dasharray: 1 1; }
.ui-flow .wires circle { fill: #C08A1E; }

/* governança: regras e registro */
.ui-audit .perm { display: grid; grid-template-columns: 1fr 1fr; gap: 1.2cqw; }
.ui-audit .perm span { display: flex; align-items: center; flex-wrap: wrap; gap: .6cqw 1.2cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.2cqw; padding: 1.3cqw 1.6cqw; font-size: 1.7cqw; font-weight: 600; }
.ui-audit .sw { width: 4cqw; height: 2.2cqw; border-radius: 99px; background: #C9D1DC; position: relative; flex: none; }
.ui-audit .sw::after { content: ""; position: absolute; top: .3cqw; left: .3cqw; width: 1.6cqw; aspect-ratio: 1; border-radius: 50%; background: #fff; }
.ui-audit .sw.on { background: #1F7A55; } .ui-audit .sw.on::after { left: auto; right: .3cqw; }
.ui-audit .perm em { font-style: normal; font-size: 1.25cqw; font-weight: 700; color: #8A5C00; background: #FBF3E2; padding: .2cqw .9cqw; border-radius: 99px; }
.ui-audit .log { background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.4cqw 2cqw; display: grid; gap: .8cqw; }
.ui-audit .log small { font-size: 1.4cqw; color: #5A6578; }
.ui-audit .log p { margin: 0; font-size: 1.6cqw; display: flex; gap: 1.6cqw; padding-top: .8cqw; border-top: 1px solid #F0F3F7; }
.ui-audit .log b { color: #8A5C00; }

/* capacitação */
.ui-course .body { flex: 1; display: grid; grid-template-columns: 1.5fr 1fr; gap: 2.4cqw; padding: 2.6cqw; }
.ui-course .player { position: relative; border-radius: 1.6cqw; background: #16233A; display: grid; place-items: center; overflow: hidden; }
.ui-course .play { width: 8cqw; aspect-ratio: 1; border-radius: 50%; background: #C08A1E; clip-path: polygon(30% 20%, 30% 80%, 80% 50%); }
.ui-course .player small { position: absolute; left: 2cqw; bottom: 3cqw; font-size: 1.6cqw; color: #fff; }
.ui-course .prog { position: absolute; left: 0; bottom: 0; height: .8cqw; width: 100%; background: #C08A1E; transform-origin: left; animation: dv-grow var(--cyc) .8s infinite both; }
.ui-course ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 1.1cqw; align-content: start; }
.ui-course li { display: flex; align-items: center; gap: 1.4cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.2cqw; padding: 1.2cqw 1.4cqw; font-size: 1.6cqw; font-weight: 600; }
.ui-course li > i { flex: none; display: grid; place-items: center; width: 3cqw; aspect-ratio: 1; border-radius: 50%; border: 1px solid #C9D1DC; font-style: normal; font-size: 1.4cqw; color: #5A6578; }
.ui-course li.ok > i { background: #1F7A55; border-color: #1F7A55; color: #fff; } .ui-course li.ok > i svg { width: 60%; }
.ui-course li.now { border-color: #C08A1E; box-shadow: 0 0 0 1px #C08A1E; } .ui-course li.now > i { background: #C08A1E; border-color: #C08A1E; color: #000; }

/* suporte */
.ui-tickets .up { display: flex; align-items: center; gap: 1.6cqw; background: #16233A; color: #fff; border-radius: 1.4cqw; padding: 1.6cqw 2cqw; }
.ui-tickets .up > i { width: 2.2cqw; aspect-ratio: 1; border-radius: 50%; background: #3FCB8A; box-shadow: 0 0 0 .8cqw rgba(63,203,138,.25); animation: dv-pulse 2.4s ease-in-out infinite; }
@keyframes dv-pulse { 50% { box-shadow: 0 0 0 1.6cqw rgba(63,203,138,0); } }
.ui-tickets .up span { display: grid; } .ui-tickets .up b { font-size: 1.9cqw; } .ui-tickets .up small { font-size: 1.4cqw; color: #C9D1DC; }
.ui-tickets .tk { display: flex; align-items: center; gap: 1.6cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.2cqw; padding: 1.3cqw 1.8cqw; }
.ui-tickets .tk > i { width: 1.4cqw; aspect-ratio: 1; border-radius: 50%; background: #C9D1DC; } .ui-tickets .tk > i.ok { background: #1F7A55; } .ui-tickets .tk > i.run { background: #C08A1E; }
.ui-tickets .tk b { flex: 1; font-size: 1.7cqw; }
.ui-tickets .tk em { font-style: normal; font-size: 1.4cqw; font-weight: 700; padding: .4cqw 1.2cqw; border-radius: 99px; background: #EEF1F5; color: #3A4558; }
.ui-tickets .tk em.ok { background: #E3F2EC; color: #1F7A55; } .ui-tickets .tk em.run { background: #FBF3E2; color: #8A5C00; }

/* palavras-chave */
.ui-kw .tb { position: relative; flex: 1; padding: 5cqw 3cqw 2cqw; display: grid; align-content: start; gap: 1cqw; }
.ui-kw .th, .ui-kw .tr { display: grid; grid-template-columns: 1.6fr 1fr 1.2fr; gap: 1.6cqw; align-items: center; }
.ui-kw .th em { font-style: normal; font-size: 1.4cqw; color: #5A6578; }
.ui-kw .tr { background: #fff; border: 1px solid #E3E8EF; border-radius: 1.2cqw; padding: 1.3cqw 1.6cqw; }
.ui-kw .tr b { font-size: 1.7cqw; }
.ui-kw .it { justify-self: start; font-size: 1.4cqw; font-weight: 700; padding: .4cqw 1.2cqw; border-radius: 99px; }
.ui-kw .i0 { background: #FBF3E2; color: #8A5C00; } .ui-kw .i1 { background: #E7ECF4; color: #2D4466; } .ui-kw .i2 { background: #E3F2EC; color: #1F7A55; } .ui-kw .i3 { background: #EEF1F5; color: #3A4558; }
.ui-kw code { font: 600 1.5cqw/1 ui-monospace, Consolas, monospace; color: #3A4558; }

/* editor do blog */
.ui-editor .body { flex: 1; display: grid; grid-template-columns: 1.6fr 1fr; gap: 2.4cqw; padding: 2.6cqw; background: #fff; }
.ui-editor .doc { display: grid; align-content: start; gap: .4cqw; }
.ui-editor .doc > b { font: 700 3cqw/1.15 var(--display); letter-spacing: -.02em; margin-bottom: 1cqw; }
.ui-editor .doc em { font-style: normal; font-weight: 700; font-size: 2cqw; margin-top: 1.4cqw; color: #16233A; }
.ui-editor aside { background: #F4F6F9; border-radius: 1.6cqw; padding: 1.8cqw; display: grid; align-content: start; gap: 1.1cqw; }
.ui-editor aside small { font-size: 1.5cqw; color: #8A5C00; font-weight: 700; }
.ui-editor aside p { margin: 0; display: flex; gap: 1cqw; align-items: center; font-size: 1.5cqw; }
.ui-editor aside p i { flex: none; display: grid; place-items: center; width: 2.4cqw; aspect-ratio: 1; border-radius: 50%; background: #1F7A55; color: #fff; } .ui-editor aside p i svg { width: 60%; }

/* marca */
.ui-brand .board { flex: 1; display: grid; grid-template-columns: 1fr 1.3fr; grid-template-rows: auto auto 1fr; align-content: start; gap: 2.4cqw; padding: 3cqw; background: #fff; }
.ui-brand .mark { grid-row: span 2; min-height: 22cqw; background: #16233A; border-radius: 1.8cqw; display: grid; place-items: center; align-content: center; gap: 1.4cqw; color: #fff; }
.ui-brand .mark i { width: 10cqw; aspect-ratio: 1; border-radius: 50%; border: 1.2cqw solid #C08A1E; border-right-color: transparent; }
.ui-brand .mark b { font: 600 2.6cqw/1 var(--display); letter-spacing: .14em; }
.ui-brand .pal { display: grid; grid-template-columns: repeat(5, 1fr); gap: 1cqw; align-self: start; }
.ui-brand .pal i { display: block; height: 7cqw; border-radius: 1.2cqw; box-shadow: inset 0 0 0 1px rgba(0,0,0,.08); }
.ui-brand .type { display: flex; align-items: center; gap: 2cqw; } .ui-brand .type b { font: 600 7cqw/1 var(--display); } .ui-brand .type span { flex: 1; }
.ui-brand .comp { grid-column: span 2; display: flex; gap: 1.6cqw; }
.ui-brand .comp i { font-style: normal; font-weight: 700; font-size: 1.7cqw; border-radius: 99px; padding: 1.2cqw 2.6cqw; }
.ui-brand .b1 { background: #C08A1E; color: #000; } .ui-brand .b2 { border: 2px solid #16233A; color: #16233A; }
.ui-feed { background: #fff; padding: 4cqw 4cqw; display: flex; flex-direction: column; gap: 4cqw; }
.ui-feed header { display: flex; align-items: center; gap: 3cqw; } .ui-feed .av { width: 14cqw; aspect-ratio: 1; border-radius: 50%; background: #16233A; box-shadow: 0 0 0 1cqw #fff, 0 0 0 1.8cqw #C08A1E; } .ui-feed header b { font-size: 6cqw; }
.ui-feed .grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.2cqw; } .ui-feed .grid i { aspect-ratio: 1; }
.ui-feed .p0 { background: #16233A; } .ui-feed .p1 { background: #C08A1E; } .ui-feed .p2 { background: #E7ECF4; }

/* plano em etapas (gantt) */
.ui-road .gantt { position: relative; flex: 1; padding: 5cqw 3cqw 2cqw; display: grid; align-content: start; gap: 1.4cqw; }
.ui-road .months { display: grid; grid-template-columns: repeat(6, 1fr); margin-left: 26%; } .ui-road .months em { font-style: normal; font-size: 1.4cqw; color: #5A6578; }
.ui-road .row { display: grid; grid-template-columns: 26% 1fr; align-items: center; }
.ui-road .row b { font-size: 1.7cqw; }
.ui-road .row span { position: relative; height: 3.4cqw; background: repeating-linear-gradient(90deg, #E9EDF3 0 1px, transparent 1px 16.66%); border-radius: .8cqw; }
.ui-road .row span i { position: absolute; top: .5cqw; bottom: .5cqw; border-radius: 99px; background: #C08A1E; transform-origin: left; animation: dv-grow var(--cyc) var(--d) infinite both !important; }
.ui-road .row:nth-child(odd) span i { background: #2D4466; }

/* celular da chamada final */
.dv-cta.dv-scene.solo { max-width: 260px; }


/* ===================== portfólio real (26/10/2026) ===================== */
/* sites criados pela Roque rolando dentro dos aparelhos; troca de site a cada ciclo */
.dv-real { --rc: 22s; }
.ui-real { display: flex; flex-direction: column; background: #000; }
.ui-real .bar span { position: relative; height: 2.6cqw; max-width: 46%; }
.ui-real .bar em { position: absolute; left: 2cqw; top: 50%; transform: translateY(-50%); font-style: normal; white-space: nowrap; }
.ui-real .vp { position: relative; flex: 1; overflow: hidden; }
.ui-real.m .vp { margin-top: 0; }
