@keyframes st-b { 0%, 42% { transform: translate3d(0,0,-140px) scale(.9); opacity: .55; z-index: 1; } 50%, 92% { transform: translate3d(14%,18%,60px) scale(1); opacity: 1; z-index: 2; } 100% { transform: translate3d(0,0,-140px) scale(.9); opacity: .55; z-index: 1; } }

