/* ---------- software sob medida (v6): um sistema que conecta as áreas da empresa. Um pedido de exemplo passa por
   Marketing, Comercial, Suprimentos, Operações, Pessoas, Financeiro, Atendimento e TI; cada área acende na sua vez (ciclo de 16 s). */
.rx .ig, .ig { position: relative; width: 1100px; height: 733px; background: #0B1220; color: #fff; font-family: var(--font-body); overflow: hidden; }
.ig-top { display: flex; align-items: baseline; gap: 16px; height: 66px; padding: 18px 28px 0; border-bottom: 1px solid rgba(255,255,255,.08); }
.ig-top b { font-size: 26px; } .ig-top span { font-size: 19px; color: #C9D1DE; } .ig-top small { margin-left: auto; font-size: 15px; color: #8FA3BF; }
.ig-svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.ig-svg line { stroke: rgba(143,163,191,.35); stroke-width: 2; animation: ig-linha 16s linear infinite; animation-delay: calc(var(--i, 0) * 2s - 16s); }
.ig-svg line.anel { stroke: rgba(192,138,30,.28); stroke-dasharray: 4 8; animation: none; }
.ig-hub { position: absolute; transform: translate(-50%, -50%); width: 150px; height: 150px; border-radius: 50%; display: grid; place-items: center; text-align: center; background: radial-gradient(closest-side, #16233A, #0B1220); border: 2px solid #C08A1E; box-shadow: 0 0 40px rgba(192,138,30,.35); font-size: 21px; font-weight: 700; line-height: 1.2; color: #F2D69C; }
.ig-no { position: absolute; transform: translate(-50%, -50%); padding: 10px 18px; border-radius: 999px; background: #16233A; border: 2px solid rgba(192,138,30,.55); font-size: 21px; font-weight: 700; white-space: nowrap; animation: ig-no 16s linear infinite; animation-delay: calc(var(--i) * 2s - 16s); }
.ig-passos { position: absolute; left: 640px; top: 90px; right: 26px; margin: 0; padding: 0; list-style: none; display: grid; gap: 8px; }
.ig-passos li { padding: 9px 16px; border-radius: 10px; background: rgba(255,255,255,.04); border-left: 4px solid rgba(192,138,30,.3); animation: ig-passo 16s linear infinite; animation-delay: calc(var(--i) * 2s - 16s); }
.ig-passos b { display: block; font-size: 19px; } .ig-passos span { font-size: 17px; color: #C9D1DE; }
@keyframes ig-no { 0%, 11% { background: #C08A1E; color: #000; border-color: #F2D69C; box-shadow: 0 0 28px rgba(192,138,30,.8); } 13%, 100% { background: #16233A; color: #fff; border-color: rgba(192,138,30,.55); box-shadow: none; } }
@keyframes ig-linha { 0%, 11% { stroke: #C08A1E; stroke-width: 5; } 13%, 100% { stroke: rgba(143,163,191,.35); stroke-width: 2; } }
@keyframes ig-passo { 0%, 11% { background: rgba(192,138,30,.22); border-left-color: #C08A1E; } 13%, 100% { background: rgba(255,255,255,.04); border-left-color: rgba(192,138,30,.3); } }
/* painel por área (tablet) */
.ig-painel { height: 800px; }
.ig-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; padding: 20px 26px; }
.ig-card { position: relative; padding: 16px 20px; border-radius: 14px; background: #16233A; border: 2px solid rgba(192,138,30,.25); animation: ig-card 16s linear infinite; animation-delay: calc(var(--i) * 2s - 16s); }
.ig-card b { display: block; font-size: 22px; color: #F2D69C; } .ig-card strong { display: block; font-size: 40px; line-height: 1.15; } .ig-card span { font-size: 18px; color: #C9D1DE; }
.ig-card i { position: absolute; right: 16px; top: 18px; font-style: normal; font-size: 15px; color: #7FD1A8; }
@keyframes ig-card { 0%, 11% { border-color: #C08A1E; box-shadow: 0 0 26px rgba(192,138,30,.55); } 13%, 100% { border-color: rgba(192,138,30,.25); box-shadow: none; } }
/* feed do pedido (celular) */
.ig-feed { width: 390px; height: 844px; padding-top: 44px; }
.ig-feed .ig-top { height: auto; padding: 14px 20px 12px; flex-wrap: wrap; } .ig-feed .ig-top b { font-size: 22px; }
.ig-feed ol { margin: 0; padding: 14px 16px; list-style: none; display: grid; gap: 9px; }
.ig-feed li { padding: 11px 14px; border-radius: 12px; background: #16233A; border-left: 4px solid rgba(192,138,30,.3); animation: ig-passo 16s linear infinite; animation-delay: calc(var(--i) * 2s - 16s); }
.ig-feed li b { display: block; font-size: 17px; color: #F2D69C; } .ig-feed li span { font-size: 15.5px; color: #C9D1DE; }

/* ---------- MAPA DAS ÁREAS (v7, pedido da Viviane): o relógio passa por cada área, a área abre as subáreas e, no fim, tudo
   fica ligado ao globo da Roque. Ciclo 22 s (8 áreas x 2.25 s + 4 s de final); só opacity/transform/cores. */
.ig2 .ig-svg line { animation: none; }
.ig2 .ig-svg .anel { stroke: rgba(192,138,30,.25); stroke-width: 2; animation: ig2-anel var(--cyc) linear infinite; }
.ig2 .ig-svg .lk { stroke: rgba(143,163,191,.32); stroke-width: 2; }
