.ui-tickets .tk > i { width: 1.4cqw; aspect-ratio: 1; border-radius: 50%; background: #C9D1DC; } .ui-tickets .tk > i.ok { background: #1F7A55; } .ui-tickets .tk > i.run { background: #C08A1E; }
.ui-tickets .tk b { flex: 1; font-size: 1.7cqw; }
.ui-tickets .tk em { font-style: normal; font-size: 1.4cqw; font-weight: 700; padding: .4cqw 1.2cqw; border-radius: 99px; background: #EEF1F5; color: #3A4558; }
.ui-tickets .tk em.ok { background: #E3F2EC; color: #1F7A55; } .ui-tickets .tk em.run { background: #FBF3E2; color: #8A5C00; }

