.rx .ig, .ig { position: relative; width: 1100px; height: 733px; background: #0B1220; color: #fff; font-family: var(--font-body); overflow: hidden; }
.ig-top { display: flex; align-items: baseline; gap: 16px; height: 66px; padding: 18px 28px 0; border-bottom: 1px solid rgba(255,255,255,.08); }
