.ig-passos { position: absolute; left: 640px; top: 90px; right: 26px; margin: 0; padding: 0; list-style: none; display: grid; gap: 8px; }
.ig-passos li { padding: 9px 16px; border-radius: 10px; background: rgba(255,255,255,.04); border-left: 4px solid rgba(192,138,30,.3); animation: ig-passo 16s linear infinite; animation-delay: calc(var(--i) * 2s - 16s); }
.ig-passos b { display: block; font-size: 19px; } .ig-passos span { font-size: 17px; color: #C9D1DE; }
@keyframes ig-no { 0%, 11% { background: #C08A1E; color: #000; border-color: #F2D69C; box-shadow: 0 0 28px rgba(192,138,30,.8); } 13%, 100% { background: #16233A; color: #fff; border-color: rgba(192,138,30,.55); box-shadow: none; } }
