html .facts li::before { content: counter(xf, decimal-leading-zero); display: block; margin-bottom: .6rem; font: 600 .82rem/1 var(--body); letter-spacing: .16em; color: var(--gold-text); }
html .facts li::after { content: ""; position: absolute; left: 1.4rem; right: 1.4rem; top: 0; height: 3px; background: var(--xg); border-radius: 0 0 3px 3px; transform: scaleX(0); transform-origin: left; transition: transform .45s cubic-bezier(.2,.7,.2,1); }
html .facts li:hover { border-color: rgba(168,112,0,.55); box-shadow: 0 22px 40px -22px rgba(22,35,58,.35); }
html .facts li:hover::after { transform: scaleX(1); }
html .facts b { display: block; font: 600 1.12rem/1.3 var(--body); color: var(--ink); margin-bottom: .25rem; }

/* ---------- colunas viram etiquetas com marca */
html .cols { list-style: none; padding: 0; max-width: none; display: grid; gap: .6rem; grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr)); margin-top: 1.6rem; }
html .cols li, html .cols li:last-child { position: relative; padding: .85rem 1rem .85rem 2.8rem; border: 1px solid var(--line); border-radius: 10px; background: var(--white); }
html .sec.white .cols li { background: var(--mist); }
html .cols li::before { content: ""; position: absolute; left: 1rem; top: 1.05rem; width: 1.05rem; height: 1.05rem; border-radius: 50%; background: var(--xg); }
html .cols li::after { content: ""; position: absolute; left: 1.33rem; top: 1.3rem; width: .4rem; height: .22rem; border-left: 2px solid #000; border-bottom: 2px solid #000; transform: rotate(-45deg); }

/* ---------- etapas: linha do tempo que se preenche com a rolagem */
html .steps { position: relative; max-width: 760px; margin-top: 2rem; --p: 0; }
html .steps::before, html .steps::after { content: ""; position: absolute; left: calc(1.35rem - 1px); top: .4rem; bottom: .4rem; width: 2px; background: var(--line); }
html .steps::after { background: var(--xg); transform: scaleY(var(--p)); transform-origin: top; }
html .steps li { padding: 0 0 2rem 4.2rem; min-height: 2.7rem; }
html .steps li:last-child { padding-bottom: 0; }
html .steps li::before { z-index: 1; width: 2.7rem; height: 2.7rem; background: var(--white); color: var(--ink); border: 2px solid var(--line); font-weight: 700; transition: background-color .4s, border-color .4s, color .4s, transform .4s cubic-bezier(.2,.7,.2,1); }
html .sec.white .steps li::before { background: var(--white); }
html .steps li.on::before { background: var(--xg); border-color: var(--xg); color: #000; transform: scale(1.08); }
html .steps b { font-size: 1.15rem; padding-top: .35rem; margin-bottom: .2rem; }

/* ---------- serviços relacionados: cartões com seta */
html .related { list-style: none; padding: 0; display: grid; gap: .8rem; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); margin-top: 1.6rem; perspective: 1000px; }
html .related a { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 1rem; min-height: 72px; padding: 1rem 1.2rem; border-radius: 12px; font: 600 1.05rem/1.3 var(--body); transform: rotateX(var(--ty, 0deg)) rotateY(var(--tx, 0deg)); transition: transform .5s cubic-bezier(.2,.7,.2,1), border-color .25s, background-color .25s, color .25s; }
html .related a::after { content: "→"; flex: none; font-size: 1.3rem; color: var(--gold-text); transition: transform .3s; }
html .related a:hover { border-color: #000; background: #000; color: #fff; }
html .related a:hover::after { color: var(--xg); transform: translateX(4px); }

/* ---------- perguntas */
html .faq { max-width: 860px; }
html .faq details { transition: background-color .3s; }
html .faq details[open] { background: rgba(168,112,0,.05); }
html .faq details[open] summary { color: var(--gold-text); }
html .faq summary, html .faq .ans { padding-left: 1rem; padding-right: 1rem; }

/* ---------- nota, grupos e destaques */
html .note { border-radius: 0 10px 10px 0; }
html .group { position: relative; margin-top: 2.2rem; padding-top: 1.6rem; border-top: 1px solid var(--line); }

/* ---------- chamada final: preta, com o celular digitando a mensagem */
html .xp-cta.sec.ink { background: #000; position: relative; overflow: hidden; }
html .xp-cta-in { display: grid; gap: 2.5rem; align-items: center; }
@media (min-width: 900px) { .xp-cta-in { grid-template-columns: minmax(0, 7fr) minmax(0, 4fr); } }
html .xp-cta h2 { color: #fff; max-width: 20ch; font-size: clamp(1.8rem, 4vw, 2.8rem); }
html .xp-cta .read { color: var(--xt2); }
html .xp-cta .btn { background: var(--xg); border-color: var(--xg); color: #000; min-height: 56px; font-size: 1.15rem; }
html .xp-cta .btn:hover { background: #D69C2A; border-color: #D69C2A; }
html .xp-cta-dev { justify-self: center; width: min(56vw, 215px); }
html .xp-cta-dev .dv-phone { width: 100%; }

/* ---------- entrada em 3D (só com JS: classe rv-on do motion.js) */
@media (prefers-reduced-motion: no-preference) {
  html.rv-on .sec h2.rv { transform: none; opacity: 0; translate: 0 .8em; transition: opacity .9s cubic-bezier(.2,.7,.2,1), translate 1s cubic-bezier(.2,.7,.2,1); }
  html.rv-on .sec h2.rv.in { opacity: 1; translate: 0 0; }
  html.rv-on .sec h2.rv::after { transform: scaleX(0); transition: transform .8s cubic-bezier(.2,.7,.2,1) .45s; }
  html.rv-on .sec h2.rv.in::after { transform: scaleX(1); }
  html.rv-on .facts li.rv, html.rv-on .related li.rv { transform: rotateX(var(--ty, 0deg)) rotateY(var(--tx, 0deg)); translate: 0 34px; rotate: x 18deg; opacity: 0;
    transition: opacity .8s cubic-bezier(.2,.7,.2,1) calc(var(--d, 0ms) * 1.4), translate .9s cubic-bezier(.2,.7,.2,1) calc(var(--d, 0ms) * 1.4), rotate .9s cubic-bezier(.2,.7,.2,1) calc(var(--d, 0ms) * 1.4), transform .5s cubic-bezier(.2,.7,.2,1), border-color .25s, box-shadow .35s; }
  html.rv-on .facts li.rv.in, html.rv-on .related li.rv.in { opacity: 1; translate: 0 0; rotate: x 0deg; }
  html.rv-on .cols li.rv { transform: none; opacity: 0; translate: -14px 0; transition: opacity .6s ease var(--d, 0ms), translate .6s cubic-bezier(.2,.7,.2,1) var(--d, 0ms); }
  html.rv-on .cols li.rv.in { opacity: 1; translate: 0 0; }
  html .xp-hero .xp-dev > * { animation: xp-dev-in 1.4s cubic-bezier(.2,.7,.2,1) .1s both; }
  html .xp-hero .btns { animation: rise .8s cubic-bezier(.2,.7,.2,1) .3s both; }
}
@keyframes xp-dev-in { from { opacity: 0; transform: translate3d(0, 40px, 0) scale(.94); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .steps::after { transform: none; } .steps li::before { background: var(--xg); border-color: var(--xg); color: #000; } }
@media print { .xp-hero.page-hero, .xp-cta.sec.ink { background: #fff; color: #000; } .xp-dev, .xp-cta-dev, .xp-floor { display: none; } }

/* APARELHOS (devices.mjs): notebook e celular realistas, sem marca, com a interface montando em câmera lenta */
.dv-scene { --cyc: 13s; contain: layout style; position: relative; width: 100%; aspect-ratio: 1.18; perspective: 1500px; isolation: isolate; }
.dv-scene.focus-phone { aspect-ratio: 1.05; }
.dv-scene.solo { aspect-ratio: auto; max-width: 300px; margin: 0 auto; }
.dv-scene.solo .dv-tilt, .dv-scene.solo .dv-rig { position: relative; inset: auto; }
.dv-scene.dv-photo { aspect-ratio: 1.5; }
.dv-tilt { --rx: 7deg; --ry: -16deg; position: absolute; inset: 0; transform-style: preserve-3d; transform: rotateX(var(--rx)) rotateY(var(--ry)); transition: transform 1.4s cubic-bezier(.2,.7,.2,1); }
.dv-scene.solo .dv-tilt { --ry: -10deg; }
.dv-scene.dv-photo .dv-tilt { --rx: 4deg; --ry: -8deg; }
.dv-rig { position: absolute; inset: 0; transform-style: preserve-3d; animation: dv-sway 22s ease-in-out infinite; }
@keyframes dv-sway { 0%, 100% { transform: rotateY(-5deg) translateY(0); } 50% { transform: rotateY(6deg) translateY(-1.2%); } }
.dv-floor { position: absolute; left: 8%; right: 8%; bottom: -2%; height: 14%; background: radial-gradient(50% 50% at 50% 50%, rgba(192,138,30,.28), rgba(192,138,30,0) 70%); filter: blur(8px); z-index: -1; pointer-events: none; }
.dv-photo img { width: 100%; height: auto; display: block; filter: drop-shadow(0 30px 40px rgba(0,0,0,.55)); }

/* ---------- notebook (estilo alumínio, sem logo) */
.dv-mac { position: absolute; left: 0; top: 3%; width: 86%; transform: translateZ(0); }
.focus-phone .dv-mac { width: 74%; top: 8%; filter: brightness(.82); }
.dv-mac .lid { background: linear-gradient(180deg, #e3e6ea, #b8bdc5); border-radius: 16px 16px 5px 5px; padding: 1.4%; box-shadow: 0 1px 0 rgba(255,255,255,.6) inset, 0 40px 70px -20px rgba(0,0,0,.7); }
.dv-mac .bezel { position: relative; background: #08090b; border-radius: 11px 11px 3px 3px; padding: 2.2% 1.8% 2.6%; }
.dv-mac .cam { position: absolute; left: 50%; top: .9%; width: 1.1%; aspect-ratio: 1; border-radius: 50%; background: #1d2b3f; transform: translateX(-50%); }
.dv-mac .screen { position: relative; aspect-ratio: 16 / 10; overflow: hidden; border-radius: 3px; background: #fff; container-type: inline-size; }
.dv-mac .base { position: relative; width: 114%; margin-left: -7%; aspect-ratio: 46 / 1; background: linear-gradient(180deg, #eef0f3 0%, #c4c8cf 55%, #9ba1aa 100%); border-radius: 2px 2px 14px 14px / 2px 2px 60px 60px; box-shadow: 0 18px 30px -8px rgba(0,0,0,.6); }
.dv-mac .base i { position: absolute; left: 50%; top: 0; width: 15%; height: 45%; transform: translateX(-50%); background: linear-gradient(180deg, #aeb3bb, #d3d6db); border-radius: 0 0 8px 8px; }

/* ---------- celular (bordas finas, ilha no topo, sem logo) */
.dv-phone { position: absolute; right: 0; bottom: 0; width: 27%; transform: translateZ(60px); }
.focus-phone .dv-phone { width: 36%; right: 4%; bottom: 0; }
.solo .dv-phone { position: relative; width: 78%; margin: 4% auto 0; transform: none; right: auto; }
.dv-phone .frame { aspect-ratio: 9 / 19.3; background: #111317; border-radius: 15% / 7.2%; padding: 3.6%; box-shadow: 0 0 0 1.5px #9ea3ab, 0 0 0 3px #d9dce0, 0 40px 60px -15px rgba(0,0,0,.75); }
.dv-phone .screen { position: relative; height: 100%; overflow: hidden; border-radius: 12% / 5.6%; background: #fff; container-type: inline-size; display: flex; flex-direction: column; }
.dv-phone .island { position: absolute; z-index: 3; left: 50%; top: 2.2%; width: 32%; height: 3.4%; transform: translateX(-50%); background: #000; border-radius: 99px; }
.dv-phone .status { flex: none; height: 7.5%; display: flex; align-items: center; justify-content: space-between; padding: 0 9%; font: 600 5cqw/1 var(--body); color: #111; }
.dv-phone .status span { width: 14%; height: 30%; border-radius: 2px; background: #111; }

/* ---------- peças que entram em sequência (atraso em --d), saem e voltam: o sistema "subindo" */
.dv [style*="--d"], .dv-scene [style*="--d"] { animation: dv-in var(--cyc) var(--d) infinite both; }
@keyframes dv-in { 0% { opacity: 0; transform: translateY(8px); } 5% { opacity: 1; transform: none; } 86% { opacity: 1; transform: none; } 93%, 100% { opacity: 0; transform: none; } }
.dv-paused * { animation-play-state: paused !important; }

.ui { position: absolute; inset: 0; font-family: var(--body); color: #16233A; }
.dv-phone .ui { position: relative; inset: auto; flex: 1; min-height: 0; }
.ui .ln { display: block; height: 1.1cqw; border-radius: 99px; background: #DCE2EA; margin: .9cqw 0; }
.ui b, .ui strong { font-weight: 700; }

/* painel (sistema sob medida) */
.ui-dash { display: grid; grid-template-columns: 15% 1fr; background: #F4F6F9; }
.ui-dash aside, .ui-inbox aside { background: #16233A; padding: 3cqw 2cqw; display: flex; flex-direction: column; gap: 1.8cqw; }
.ui-dash .logo, .ui-inbox .logo { width: 4cqw; aspect-ratio: 1; border-radius: 1cqw; background: #C08A1E; margin-bottom: 1.5cqw; }
.ui-dash .nav, .ui-inbox .nav { height: 1.3cqw; border-radius: 99px; background: rgba(255,255,255,.22); }
.ui-dash .nav.on, .ui-inbox .nav.on { background: #C08A1E; }
.ui-dash .ui-main { padding: 2.6cqw 3cqw; display: grid; grid-template-rows: auto auto 1fr auto; gap: 2cqw; min-width: 0; }
.ui-dash header, .ui-inbox header { display: flex; align-items: center; gap: 1.6cqw; }
.ui-dash header b, .ui-inbox header b { font-size: 2.6cqw; }
.ui-dash header small, .ui-inbox header small { font-size: 1.5cqw; color: #8A5C00; background: #FBF3E2; padding: .4cqw 1cqw; border-radius: 99px; }
.ui-dash header .av { margin-left: auto; width: 3.4cqw; aspect-ratio: 1; border-radius: 50%; background: #C9D1DC; }
.ui-dash .kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.6cqw; }
.ui-dash .kpi { background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.6cqw 2cqw; display: grid; gap: .5cqw; }
.ui-dash .kpi small { font-size: 1.5cqw; color: #5A6578; }
.ui-dash .kpi b { font-size: 3.4cqw; line-height: 1; }
.ui-dash .kpi.g { background: #16233A; color: #fff; border-color: #16233A; }
.ui-dash .kpi.g small { color: #B9C3D1; }
.ui-dash .chart { background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.6cqw 2cqw; display: grid; grid-template-rows: auto 1fr; min-height: 0; }
.ui-dash .chart small { font-size: 1.5cqw; color: #5A6578; }
.ui-dash .bars { display: flex; align-items: flex-end; gap: 1.6cqw; padding-top: 1.4cqw; min-height: 0; }
.ui-dash .bars i { flex: 1; height: var(--h); background: linear-gradient(180deg, #C08A1E, #A87000); border-radius: .8cqw .8cqw 0 0; transform-origin: bottom; animation: dv-bar var(--cyc) var(--d) infinite both !important; }
.ui-dash .bars i:nth-child(odd) { background: #2D4466; }
@keyframes dv-bar { 0% { transform: scaleY(0); } 6% { transform: scaleY(1); } 86% { transform: scaleY(1); } 93%, 100% { transform: scaleY(0); } }
.ui-dash .table { display: grid; grid-template-columns: 1.3fr 1fr 1fr; gap: .2cqw 0; font-size: 1.5cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.2cqw 2cqw; }
.ui-dash .table em { font-style: normal; color: #5A6578; padding-bottom: .6cqw; border-bottom: 1px solid #E3E8EF; }
.ui-dash .tr { display: contents; }
.ui-dash .tr > span { padding: .7cqw 0; border-bottom: 1px solid #F0F3F7; }
.ui-dash .tr .tag { justify-self: start; color: #8A5C00; }

/* aplicativo (celular) */
.ui-app { background: #F4F6F9; padding: 4cqw 6cqw 0; display: flex; flex-direction: column; gap: 4cqw; }
.ui-app header small { display: block; font-size: 6cqw; color: #5A6578; }
.ui-app header b { font-size: 9.5cqw; line-height: 1.1; }
.ui-app .card { display: flex; gap: 4cqw; align-items: center; background: #fff; border-radius: 5cqw; padding: 4.5cqw 5cqw; box-shadow: 0 1px 0 #E3E8EF; border-left: 2.2cqw solid #C08A1E; }
.ui-app .card:nth-of-type(even) { border-left-color: #2D4466; }
.ui-app .card > b { font-size: 6.5cqw; }
.ui-app .card span { display: grid; }
.ui-app .card strong { font-size: 6.5cqw; }
.ui-app .card small { font-size: 5.5cqw; color: #5A6578; }
.ui-app .toast { position: absolute; left: 4cqw; right: 4cqw; top: 3cqw; z-index: 2; display: flex; gap: 4cqw; align-items: center; background: rgba(22,35,58,.94); color: #fff; border-radius: 6cqw; padding: 4.5cqw 5cqw; box-shadow: 0 12px 24px rgba(0,0,0,.25); }
.ui-app .toast i { width: 9cqw; aspect-ratio: 1; border-radius: 2.5cqw; background: #C08A1E; flex: none; }
.ui-app .toast span { display: grid; }
.ui-app .toast strong { font-size: 6cqw; }
.ui-app .toast small { font-size: 5.2cqw; color: #C9D1DC; }
.ui-app nav { margin-top: auto; display: flex; justify-content: space-around; padding: 4cqw 0 7cqw; background: #fff; margin-left: -6cqw; margin-right: -6cqw; }
.ui-app nav i { width: 8cqw; aspect-ratio: 1; border-radius: 2cqw; background: #C9D1DC; }
.ui-app nav i.on { background: #C08A1E; }

/* navegador e site */
.ui-browser, .ui-serp { display: flex; flex-direction: column; background: #fff; }
.ui .bar { flex: none; display: flex; align-items: center; gap: .9cqw; padding: 1.3cqw 1.8cqw; background: #EDEFF2; border-bottom: 1px solid #DDE1E6; }
.ui .bar > i { width: 1.3cqw; aspect-ratio: 1; border-radius: 50%; background: #C7CCD3; }
.ui .bar span { margin-left: 2cqw; flex: 1; max-width: 50%; font-size: 1.6cqw; color: #5A6578; background: #fff; border-radius: 99px; padding: .5cqw 2cqw; }
.ui-browser .site { flex: 1; padding: 0 4cqw; display: grid; grid-template-rows: auto 1fr auto; }
.ui-browser .nav { display: flex; align-items: center; gap: 2.4cqw; padding: 2cqw 0; border-bottom: 1px solid #EEF1F5; }
.ui-browser .nav .logo { width: 10cqw; height: 2.4cqw; border-radius: 99px; background: #16233A; margin-right: auto; }
.ui-browser .nav .ln { margin: 0; }
.ui-browser .nav .cta { width: 10cqw; height: 3cqw; border-radius: 99px; background: #C08A1E; }
.ui-browser .hero { display: grid; grid-template-columns: 1.1fr 1fr; gap: 3cqw; align-items: center; padding: 3cqw 0; }
.ui-browser .hero b { display: block; font: 700 4.2cqw/1.1 var(--display); letter-spacing: -.02em; }
.ui-browser .hero .ln { height: 1.2cqw; }
.ui-browser .btn, .ui-msite .btn { display: inline-flex; margin-top: 1.6cqw; font-style: normal; font-weight: 700; font-size: 1.7cqw; color: #fff; background: #1F7A55; border-radius: 99px; padding: 1.1cqw 2.6cqw; }
.ui-browser .hero .img { display: block; aspect-ratio: 4/3; border-radius: 2cqw; background: linear-gradient(135deg, #16233A, #2D4466 60%, #C08A1E); }
.ui-browser .cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2cqw; padding-bottom: 3cqw; }
.ui-browser .col { border: 1px solid #E3E8EF; border-radius: 1.6cqw; padding: 1.8cqw; }
.ui-browser .col .ic { display: block; width: 3.6cqw; aspect-ratio: 1; border-radius: 1cqw; background: #FBF3E2; border: 1px solid #C08A1E; }
.ui-msite { background: #fff; padding: 3cqw 7cqw; display: flex; flex-direction: column; gap: 4cqw; }
.ui-msite .mnav { display: flex; justify-content: space-between; align-items: center; }
.ui-msite .logo { width: 30cqw; height: 6cqw; border-radius: 99px; background: #16233A; }
.ui-msite .burger { width: 8cqw; height: 6cqw; border-top: 1.4cqw solid #16233A; border-bottom: 1.4cqw solid #16233A; }
.ui-msite > b { font: 700 11cqw/1.08 var(--display); letter-spacing: -.02em; }
.ui-msite .ln { height: 3cqw; margin: 2.4cqw 0; }
.ui-msite .btn { font-size: 6.5cqw; padding: 4cqw 7cqw; justify-content: center; margin-top: 0; }
.ui-msite .img { display: block; aspect-ratio: 4/3; border-radius: 5cqw; background: linear-gradient(135deg, #16233A, #2D4466 60%, #C08A1E); }
.ui-msite .wa { position: absolute; right: 6cqw; bottom: 8cqw; width: 18cqw; aspect-ratio: 1; border-radius: 50%; background: #1F7A55; box-shadow: 0 8px 16px rgba(0,0,0,.25); }

/* resultados de busca: o site do cliente sobe até o primeiro lugar */
.ui-serp .q { margin: 2.4cqw 4cqw 1.4cqw; display: flex; align-items: center; gap: 1.6cqw; font-size: 2cqw; border: 1px solid #DDE1E6; border-radius: 99px; padding: 1.3cqw 2.6cqw; box-shadow: 0 2px 6px rgba(0,0,0,.06); }
.ui-serp .mg, .ui-mserp .mg { width: 2cqw; aspect-ratio: 1; border-radius: 50%; border: .45cqw solid #5A6578; flex: none; }
.ui-serp .res { position: relative; flex: 1; margin: 0 4cqw 2cqw; animation: dv-fade var(--cyc) infinite both; }
.ui-serp .r { position: absolute; left: 0; right: 0; height: 18%; padding: 1cqw 1.6cqw; border-radius: 1.4cqw; display: grid; align-content: center; gap: .3cqw; }
.ui-serp .r small { font-size: 1.4cqw; color: #5A6578; }
.ui-serp .r b { display: block; font-size: 1.9cqw; line-height: 1.3; color: #1A0DAB; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ui-serp .r small { display: block; line-height: 1.2; }
.ui-serp .r span { font-size: 1.45cqw; color: #4D5156; line-height: 1.35; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.ui-serp .me { background: #FBF3E2; box-shadow: 0 0 0 2px #C08A1E; z-index: 2; }
.ui-serp .me b { font-size: 1.9cqw; color: #16233A; }
.ui-serp .me small { color: #8A5C00; font-weight: 700; }
.ui-serp .r0 { animation: dv-r0 var(--cyc) infinite; } .ui-serp .r1 { animation: dv-r1 var(--cyc) infinite; }
.ui-serp .r2 { animation: dv-r2 var(--cyc) infinite; } .ui-serp .r3 { animation: dv-r3 var(--cyc) infinite; }
.ui-serp .me { animation: dv-me var(--cyc) infinite; }
