.ui-flow .node b { font-size: 1.8cqw; }
.ui-flow .node small { font-size: 1.4cqw; color: #5A6578; }
.ui-flow .wires { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.ui-flow .wires path { fill: none; stroke: #9DAAC0; stroke-width: .35; stroke-dasharray: 1 1; }
.ui-flow .wires circle { fill: #C08A1E; }

/* governança: regras e registro */
.ui-audit .perm { display: grid; grid-template-columns: 1fr 1fr; gap: 1.2cqw; }
.ui-audit .perm span { display: flex; align-items: center; flex-wrap: wrap; gap: .6cqw 1.2cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.2cqw; padding: 1.3cqw 1.6cqw; font-size: 1.7cqw; font-weight: 600; }
.ui-audit .sw { width: 4cqw; height: 2.2cqw; border-radius: 99px; background: #C9D1DC; position: relative; flex: none; }
.ui-audit .sw::after { content: ""; position: absolute; top: .3cqw; left: .3cqw; width: 1.6cqw; aspect-ratio: 1; border-radius: 50%; background: #fff; }
.ui-audit .sw.on { background: #1F7A55; } .ui-audit .sw.on::after { left: auto; right: .3cqw; }
.ui-audit .perm em { font-style: normal; font-size: 1.25cqw; font-weight: 700; color: #8A5C00; background: #FBF3E2; padding: .2cqw .9cqw; border-radius: 99px; }
.ui-audit .log { background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.4cqw 2cqw; display: grid; gap: .8cqw; }
.ui-audit .log small { font-size: 1.4cqw; color: #5A6578; }
.ui-audit .log p { margin: 0; font-size: 1.6cqw; display: flex; gap: 1.6cqw; padding-top: .8cqw; border-top: 1px solid #F0F3F7; }
.ui-audit .log b { color: #8A5C00; }

/* capacitação */
.ui-course .body { flex: 1; display: grid; grid-template-columns: 1.5fr 1fr; gap: 2.4cqw; padding: 2.6cqw; }
.ui-course .player { position: relative; border-radius: 1.6cqw; background: #16233A; display: grid; place-items: center; overflow: hidden; }
.ui-course .play { width: 8cqw; aspect-ratio: 1; border-radius: 50%; background: #C08A1E; clip-path: polygon(30% 20%, 30% 80%, 80% 50%); }
.ui-course .player small { position: absolute; left: 2cqw; bottom: 3cqw; font-size: 1.6cqw; color: #fff; }
.ui-course .prog { position: absolute; left: 0; bottom: 0; height: .8cqw; width: 100%; background: #C08A1E; transform-origin: left; animation: dv-grow var(--cyc) .8s infinite both; }
.ui-course ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 1.1cqw; align-content: start; }
