/* ===================== portfólio real (26/10/2026) ===================== */
/* sites criados pela Roque rolando dentro dos aparelhos; troca de site a cada ciclo */
.dv-real { --rc: 22s; }
.ui-real { display: flex; flex-direction: column; background: #000; }
.ui-real .bar span { position: relative; height: 2.6cqw; max-width: 46%; }
.ui-real .bar em { position: absolute; left: 2cqw; top: 50%; transform: translateY(-50%); font-style: normal; white-space: nowrap; }
.ui-real .vp { position: relative; flex: 1; overflow: hidden; }
.ui-real.m .vp { margin-top: 0; }
.ui-real .vp img { position: absolute; left: 0; top: 0; width: 100%; height: auto; display: block; will-change: transform, opacity; }
.dv-real .s1, .dv-real .u1 { animation: rs-s1 var(--rc) cubic-bezier(.45,.05,.35,1) infinite; }
.dv-real .s2, .dv-real .u2 { animation: rs-s2 var(--rc) cubic-bezier(.45,.05,.35,1) infinite; }
.dv-real .ui-real:not(.m) .vp img { --end: -74%; }
.dv-real .ui-real.m .vp img { --end: -61%; }
.dv-real .u1, .dv-real .u2 { --end: 0; }
@keyframes rs-s1 { 0% { opacity: 1; transform: translateY(0); } 7% { transform: translateY(0); } 40% { opacity: 1; transform: translateY(var(--end)); } 46% { opacity: 1; transform: translateY(var(--end)); } 50%, 95% { opacity: 0; transform: translateY(var(--end)); } 96% { opacity: 0; transform: translateY(0); } 100% { opacity: 1; transform: translateY(0); } }
@keyframes rs-s2 { 0%, 45% { opacity: 0; transform: translateY(0); } 50% { opacity: 1; transform: translateY(0); } 57% { transform: translateY(0); } 90% { opacity: 1; transform: translateY(var(--end)); } 96% { opacity: 1; transform: translateY(var(--end)); } 100% { opacity: 0; transform: translateY(var(--end)); } }
.ui-real.m { background: #000; }
.dv-real .dv-phone .status { position: relative; z-index: 2; background: transparent; color: #fff; }
.dv-real .dv-phone .status span { background: #fff; }
.dv-real .dv-phone .screen { background: #000; }

/* selos flutuando em profundidade (3D de verdade: translateZ dentro do rig) */
.rs-chips { position: absolute; inset: 0; transform-style: preserve-3d; pointer-events: none; }
.rs-chips span { position: absolute; display: inline-flex; align-items: center; gap: .45em; white-space: nowrap; font: 600 clamp(.62rem, 1.35vw, .86rem)/1 var(--body); color: #fff; background: rgba(12,16,24,.82); border: 1px solid rgba(192,138,30,.55); border-radius: 99px; padding: .55em .95em; box-shadow: 0 14px 30px -10px rgba(0,0,0,.6); backdrop-filter: none; }
.rs-chips span::before { content: ""; width: .55em; height: .55em; border-radius: 50%; background: #C08A1E; box-shadow: 0 0 0 .25em rgba(192,138,30,.25); }
.rs-chips .c1 { left: -6%; top: 46%; transform: translateZ(140px); }
.rs-chips .c2 { right: 24%; top: -9%; transform: translateZ(90px); }
.rs-chips .c3 { left: 10%; bottom: 8%; transform: translateZ(180px); }
