  html.rv-on .sec h2.rv::after { transform: scaleX(0); transition: transform .8s cubic-bezier(.2,.7,.2,1) .45s; }
  html.rv-on .sec h2.rv.in::after { transform: scaleX(1); }
  html.rv-on .facts li.rv, html.rv-on .related li.rv { transform: rotateX(var(--ty, 0deg)) rotateY(var(--tx, 0deg)); translate: 0 34px; rotate: x 18deg; opacity: 0;
    transition: opacity .8s cubic-bezier(.2,.7,.2,1) calc(var(--d, 0ms) * 1.4), translate .9s cubic-bezier(.2,.7,.2,1) calc(var(--d, 0ms) * 1.4), rotate .9s cubic-bezier(.2,.7,.2,1) calc(var(--d, 0ms) * 1.4), transform .5s cubic-bezier(.2,.7,.2,1), border-color .25s, box-shadow .35s; }
