.ui-chat .out i svg { width: 100%; height: auto; display: block; }
.ui-chat .typing { align-self: flex-start; background: #fff; display: flex; gap: 1.6cqw; padding: 3.6cqw 4.5cqw; }
.ui-chat .typing i { width: 2.4cqw; aspect-ratio: 1; border-radius: 50%; background: #9AA4B2; }
.ui-chat .input { margin: 0 4cqw 7cqw; height: 11cqw; border-radius: 99px; background: #fff; }

/* caixa de conversas (notebook) */
.ui-inbox { display: grid; grid-template-columns: 15% 1fr; background: #F4F6F9; }
.ui-inbox .ui-main { padding: 3cqw; display: flex; flex-direction: column; gap: 1.6cqw; }
.ui-inbox .conv { display: flex; align-items: center; gap: 2cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.6cqw 2cqw; }
.ui-inbox .conv .av { width: 4cqw; aspect-ratio: 1; border-radius: 50%; background: #C9D1DC; flex: none; }
.ui-inbox .conv span { display: grid; flex: 1; min-width: 0; }
.ui-inbox .conv b { font-size: 1.9cqw; }
.ui-inbox .conv small { font-size: 1.6cqw; color: #5A6578; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ui-inbox .conv em { font-style: normal; font-size: 1.5cqw; font-weight: 700; padding: .5cqw 1.4cqw; border-radius: 99px; }
.ui-inbox .conv em.ok { background: #E3F2EC; color: #1F7A55; }
.ui-inbox .conv em.hu { background: #FBF3E2; color: #8A5C00; }


/* ===================== telas novas (26/10/2026) ===================== */
.ui-chat .msgs { justify-content: flex-end; overflow: hidden; }
.ui-chat .intent, .ui-chat .src { align-self: center; max-width: none; box-shadow: none; padding: 1.4cqw 3.4cqw; font-size: 4.4cqw; font-weight: 700; border-radius: 99px; }
.ui-chat .intent { background: #16233A; color: #F2D69C; }
.ui-chat .src { background: rgba(255,255,255,.7); color: #5A6578; font-weight: 600; }
/* texto das bolhas: cor própria, sem herdar o branco da seção escura (contraste) */
.ui.ui-chat p { color: #16233A; }
.ui.ui-chat p.src, .ui.ui-chat p.src small { color: #5A6578; }
.ui-eng p:not(.intent):not(.src) { font-size: 5.4cqw; }
.ui-compose .av.rq { background: #000 url(/img/roque-simbolo.png) center/70% no-repeat; }
.ui-compose .msgs { justify-content: flex-end; }
.ui-compose .sent { opacity: 0; animation: dv-sent 9s infinite both; }
.ui-compose .input { display: flex; align-items: center; gap: 3cqw; height: auto; min-height: 11cqw; padding: 2.4cqw 3cqw 2.4cqw 5cqw; border-radius: 6cqw; }
.ui-compose .typed { flex: 1; font-size: 5.2cqw; line-height: 1.3; color: #16233A; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; clip-path: inset(0 100% 0 0); animation: dv-type 9s steps(28) infinite both; }
.ui-compose .send { flex: none; width: 9cqw; aspect-ratio: 1; border-radius: 50%; background: #1F7A55; }
@keyframes dv-type { 0% { clip-path: inset(0 100% 100% 0); opacity: 1; } 45% { clip-path: inset(0 0 0 0); opacity: 1; } 55% { clip-path: inset(0 0 0 0); opacity: 1; } 58%, 100% { opacity: 0; } }
@keyframes dv-sent { 0%, 57% { opacity: 0; transform: translateY(6px); } 62%, 94% { opacity: 1; transform: none; } 100% { opacity: 0; } }

/* chat no site */
.ui-webchat { position: absolute; }
.ui-webchat .wc { position: absolute; right: 3cqw; bottom: 9cqw; width: 34cqw; background: #fff; border-radius: 1.8cqw; box-shadow: 0 2cqw 5cqw rgba(22,35,58,.28); padding: 0 0 1.6cqw; display: flex; flex-direction: column; gap: 1cqw; overflow: hidden; }
.ui-webchat .wc header { display: flex; align-items: center; gap: 1.2cqw; background: #16233A; color: #fff; padding: 1.4cqw 1.8cqw; }
.ui-webchat .wc header .av { width: 2.8cqw; aspect-ratio: 1; border-radius: 50%; background: #C08A1E; }
.ui-webchat .wc header b { font-size: 1.7cqw; }
.ui-webchat .wc header small { margin-left: auto; font-size: 1.3cqw; color: #F2D69C; }
.ui-webchat .wc p { margin: 0 1.6cqw; padding: 1cqw 1.4cqw; font-size: 1.55cqw; line-height: 1.3; border-radius: 1.2cqw; max-width: 82%; }
.ui-webchat .wc .in { align-self: flex-start; background: #EEF1F5; }
.ui-webchat .wc .out { align-self: flex-end; background: #FBF3E2; color: #16233A; }
.ui-webchat .wc .intent { align-self: center; background: #16233A; color: #F2D69C; font-weight: 700; font-size: 1.25cqw; border-radius: 99px; padding: .5cqw 1.4cqw; }
.ui-webchat .wc .field { display: block; margin: .4cqw 1.6cqw 0; height: 3cqw; border: 1px solid #DDE1E6; border-radius: 99px; }
.ui-webchat .launcher { position: absolute; right: 3cqw; bottom: 2.4cqw; width: 5cqw; aspect-ratio: 1; border-radius: 50%; background: #16233A; box-shadow: 0 1cqw 2cqw rgba(0,0,0,.25); }

/* caixa de conversas do EngageBot: canal de cada conversa */
.ui-inbox .conv .ch { font-style: normal; font-size: 1.2cqw; font-weight: 700; padding: .2cqw .9cqw; border-radius: 99px; margin-left: .6cqw; vertical-align: middle; }
.ui-inbox .conv .ch.wa { background: #E3F2EC; color: #1F7A55; }
.ui-inbox .conv .ch.web { background: #E7ECF4; color: #2D4466; }

/* base de conhecimento */
.ui-kb, .ui-audit, .ui-tickets { display: grid; grid-template-columns: 15% 1fr; background: #F4F6F9; }
.ui-kb aside, .ui-audit aside, .ui-tickets aside { background: #16233A; padding: 3cqw 2cqw; display: flex; flex-direction: column; gap: 1.8cqw; }
.ui-kb .logo, .ui-audit .logo, .ui-tickets .logo { width: 4cqw; aspect-ratio: 1; border-radius: 1cqw; background: #C08A1E; margin-bottom: 1.5cqw; }
.ui-kb .nav, .ui-audit .nav, .ui-tickets .nav { height: 1.3cqw; border-radius: 99px; background: rgba(255,255,255,.22); }
.ui-kb .nav.on, .ui-audit .nav.on, .ui-tickets .nav.on { background: #C08A1E; }
.ui-kb .ui-main, .ui-audit .ui-main, .ui-tickets .ui-main { padding: 3cqw; display: flex; flex-direction: column; gap: 1.5cqw; min-width: 0; }
.ui-kb header, .ui-audit header, .ui-tickets header { display: flex; align-items: center; gap: 1.6cqw; }
.ui-kb header b, .ui-audit header b, .ui-tickets header b { font-size: 2.6cqw; }
.ui-kb header small, .ui-audit header small, .ui-tickets header small { font-size: 1.5cqw; color: #8A5C00; background: #FBF3E2; padding: .4cqw 1cqw; border-radius: 99px; }
.ui-kb .src { position: relative; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: .6cqw 2cqw; background: #fff; border: 1px solid #E3E8EF; border-radius: 1.4cqw; padding: 1.4cqw 2cqw 2cqw; }
.ui-kb .src .ic { font-style: normal; display: grid; place-items: center; width: 4.6cqw; aspect-ratio: 1; border-radius: 1cqw; background: #FBF3E2; color: #8A5C00; font-size: 1.3cqw; font-weight: 700; }
.ui-kb .src .ic.site { background: #E7ECF4; color: #2D4466; }
.ui-kb .src span { display: grid; min-width: 0; }
.ui-kb .src b { font-size: 1.8cqw; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ui-kb .src small { font-size: 1.4cqw; color: #5A6578; }
.ui-kb .src em { font-style: normal; font-size: 1.4cqw; font-weight: 700; color: #1F7A55; background: #E3F2EC; padding: .4cqw 1.2cqw; border-radius: 99px; }
.ui-kb .src .bar { position: absolute; left: 2cqw; right: 2cqw; bottom: .8cqw; height: .5cqw; border-radius: 99px; background: #C08A1E; transform-origin: left; animation: dv-grow var(--cyc) var(--d) infinite both !important; padding: 0; border: 0; }
@keyframes dv-grow { 0% { transform: scaleX(0); } 8% { transform: scaleX(1); } 86% { transform: scaleX(1); } 93%, 100% { transform: scaleX(0); } }
.ui-kb .ask { margin-top: auto; background: #16233A; color: #fff; border-radius: 1.4cqw; padding: 1.6cqw 2cqw; display: grid; gap: .4cqw; }
.ui-kb .ask small { font-size: 1.3cqw; color: #F2D69C; }
.ui-kb .ask b { font-size: 1.8cqw; }
.ui-kb .ask span { font-size: 1.6cqw; color: #C9D1DC; }

/* ativação guiada (celular) */
.ui-act { background: #F4F6F9; padding: 5cqw 6cqw; display: flex; flex-direction: column; gap: 3.6cqw; }
.ui-act header small { display: block; font-size: 5.4cqw; color: #8A5C00; font-weight: 700; }
.ui-act header b { font-size: 8.6cqw; line-height: 1.1; }
.ui-act .st { display: flex; align-items: center; gap: 4cqw; background: #fff; border-radius: 4.5cqw; padding: 4cqw 4.5cqw; box-shadow: 0 1px 0 #E3E8EF; }
.ui-act .st > i { flex: none; display: grid; place-items: center; width: 10cqw; aspect-ratio: 1; border-radius: 50%; background: #1F7A55; color: #fff; font-style: normal; font-weight: 700; font-size: 5cqw; }
.ui-act .st > i svg { width: 60%; }
.ui-act .st.now > i { background: #C08A1E; color: #000; }
.ui-act .st span { display: grid; }
.ui-act .st strong { font-size: 5.6cqw; }
.ui-act .st small { font-size: 4.6cqw; color: #5A6578; }
.ui-act .go { margin-top: auto; margin-bottom: 6cqw; font-style: normal; text-align: center; font-weight: 700; font-size: 6cqw; background: #16233A; color: #fff; border-radius: 99px; padding: 4.4cqw; }

/* CRM: funil em colunas, um cartão atravessa as etapas */
.ui-kanban, .ui-flow, .ui-course, .ui-kw, .ui-editor, .ui-brand, .ui-road { display: flex; flex-direction: column; background: #F4F6F9; }
.ui .tag { position: absolute; right: 3cqw; top: 1.6cqw; font-size: 1.4cqw; color: #8A5C00; background: #FBF3E2; padding: .4cqw 1cqw; border-radius: 99px; z-index: 2; }
.ui-kanban .board { position: relative; flex: 1; display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.8cqw; padding: 5cqw 2.6cqw 2.6cqw; }
.ui-kanban .col { background: #E9EDF3; border-radius: 1.4cqw; padding: 1.4cqw; display: flex; flex-direction: column; gap: 1.2cqw; }
.ui-kanban .col > b { font-size: 1.6cqw; color: #3A4558; }
.ui-kanban .card { background: #fff; border-radius: 1cqw; padding: 1.2cqw 1.4cqw; box-shadow: 0 1px 0 #D8DDE5; display: grid; }
.ui-kanban .card strong { font-size: 1.6cqw; }
.ui-kanban .card .ln { height: .9cqw; margin: .8cqw 0 0; }
.ui-kanban .mover { position: absolute; top: 24cqw; left: 4cqw; width: calc((100% - 5.2cqw - 5.4cqw) / 4 - 2.8cqw); border-left: .8cqw solid #C08A1E; box-shadow: 0 1.4cqw 3cqw rgba(22,35,58,.22); animation: dv-move var(--cyc) infinite both; z-index: 3; }
@keyframes dv-move { 0%, 12% { transform: translateX(0) rotate(0); opacity: 0; } 16% { opacity: 1; } 28%, 36% { transform: translateX(calc(100% + 4.2cqw)) rotate(-2deg); } 50%, 58% { transform: translateX(calc(200% + 8.4cqw)) rotate(1deg); } 72%, 92% { transform: translateX(calc(300% + 12.6cqw)) rotate(0); opacity: 1; } 100% { opacity: 0; transform: translateX(calc(300% + 12.6cqw)); } }

/* automação: blocos ligados, com o dado correndo nos fios */
.ui-flow .canvas { position: relative; flex: 1; background: radial-gradient(#D5DCE6 1px, transparent 1.2px) 0 0 / 3cqw 3cqw; }
.ui-flow .node { position: absolute; width: 24%; background: #fff; border-radius: 1.4cqw; padding: 1.4cqw 1.8cqw; display: grid; gap: .2cqw; box-shadow: 0 1cqw 2.4cqw rgba(22,35,58,.14); border-top: .6cqw solid #C08A1E; z-index: 1; }
